#!/usr/bin/env node
const fs = require("fs");
const path = require("path");
const { spawnSync } = require("child_process");

const ROOT = process.cwd();
const EVALS_DIR = path.join(ROOT, "evals");

const KEYWORDS = new Set([
  "await", "async", "break", "case", "catch", "class", "const", "continue",
  "debugger", "default", "delete", "do", "else", "export", "extends",
  "false", "finally", "for", "from", "function", "if", "import", "in", "instanceof",
  "let", "new", "null", "of", "return", "static", "super", "switch", "this",
  "throw", "try", "typeof", "var", "void", "while", "with", "yield",
  "true",
]);

const KNOWN_GLOBALS = new Set([
  "Array", "ArrayBuffer", "BigInt", "Boolean", "DataView", "Date", "Error",
  "EvalError", "Event", "Float32Array", "Float64Array", "Infinity", "Intl",
  "JSON", "Map", "Math", "NaN", "Number", "Object", "Promise", "Proxy",
  "RangeError", "ReferenceError", "Reflect", "RegExp", "Set", "String",
  "Symbol", "SyntaxError", "THREE", "TypeError", "URIError", "URL",
  "WeakMap", "WeakSet", "alert", "cancelAnimationFrame", "clearInterval",
  "clearTimeout", "console", "decodeURIComponent", "document",
  "encodeURIComponent", "fetch", "globalThis", "isFinite", "isNaN",
  "localStorage", "module", "parseFloat", "parseInt", "performance",
  "requestAnimationFrame", "setInterval", "setTimeout", "undefined", "window",
]);

function isIdent(value) {
  return /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(value);
}

function stripStringsAndComments(source) {
  let out = "";
  for (let i = 0; i < source.length;) {
    const ch = source[i];
    const next = source[i + 1];
    if (ch === "/" && next === "/") {
      out += "  ";
      i += 2;
      while (i < source.length && source[i] !== "\n") {
        out += " ";
        i += 1;
      }
      continue;
    }
    if (ch === "/" && next === "*") {
      out += "  ";
      i += 2;
      while (i < source.length && !(source[i] === "*" && source[i + 1] === "/")) {
        out += source[i] === "\n" ? "\n" : " ";
        i += 1;
      }
      if (i < source.length) {
        out += "  ";
        i += 2;
      }
      continue;
    }
    if (ch === "\"" || ch === "'" || ch === "`") {
      const quote = ch;
      out += " ";
      i += 1;
      while (i < source.length) {
        if (source[i] === "\\") {
          out += " ";
          i += 1;
          if (i < source.length) {
            out += source[i] === "\n" ? "\n" : " ";
            i += 1;
          }
          continue;
        }
        if (source[i] === quote) {
          out += " ";
          i += 1;
          break;
        }
        out += source[i] === "\n" ? "\n" : " ";
        i += 1;
      }
      continue;
    }
    out += ch;
    i += 1;
  }
  return out;
}

function tokenize(source) {
  const stripped = stripStringsAndComments(source);
  const tokens = [];
  const re = /0x[0-9A-Fa-f]+|\d+(?:\.\d+)?|[A-Za-z_$][A-Za-z0-9_$]*|=>|===|!==|==|!=|<=|>=|\+\+|--|&&|\|\||[{}()[\].,;:=+\-*/%<>!?]/g;
  const lineStarts = [0];
  for (let i = 0; i < stripped.length; i += 1) {
    if (stripped[i] === "\n") lineStarts.push(i + 1);
  }
  function position(index) {
    let lo = 0;
    let hi = lineStarts.length - 1;
    while (lo <= hi) {
      const mid = Math.floor((lo + hi) / 2);
      if (lineStarts[mid] <= index) lo = mid + 1;
      else hi = mid - 1;
    }
    const lineIndex = Math.max(0, hi);
    return { line: lineIndex + 1, column: index - lineStarts[lineIndex] + 1 };
  }
  let match;
  while ((match = re.exec(stripped))) {
    tokens.push({ value: match[0], index: match.index, ...position(match.index) });
  }
  return tokens;
}

function makeScope(parent, kind, file) {
  return { parent, kind, file, declarations: new Set(), refs: [], children: [] };
}

function declare(scope, name) {
  if (name && isIdent(name) && !KEYWORDS.has(name)) scope.declarations.add(name);
}

function nearestFunctionScope(scope) {
  let current = scope;
  while (current && current.kind !== "function" && current.kind !== "root") {
    current = current.parent;
  }
  return current || scope;
}

function parseParamNames(tokens, startIndex) {
  const params = [];
  const paramIndices = [];
  let depth = 0;
  for (let i = startIndex; i < tokens.length; i += 1) {
    const value = tokens[i].value;
    if (value === "(") {
      depth += 1;
      continue;
    }
    if (value === ")") {
      depth -= 1;
      if (depth === 0) return { params, paramIndices, end: i };
      continue;
    }
    if (depth === 1 && isIdent(value) && !KEYWORDS.has(value)) {
      params.push(value);
      paramIndices.push(i);
    }
  }
  return { params, paramIndices, end: startIndex };
}

function arrowParamsBefore(tokens, arrowIndex) {
  const prev = tokens[arrowIndex - 1];
  if (!prev) return [];
  if (isIdent(prev.value) && !KEYWORDS.has(prev.value)) return [{ name: prev.value, tokenIndex: arrowIndex - 1 }];
  if (prev.value !== ")") return [];
  let depth = 0;
  for (let i = arrowIndex - 1; i >= 0; i -= 1) {
    const value = tokens[i].value;
    if (value === ")") depth += 1;
    else if (value === "(") {
      depth -= 1;
      if (depth === 0) {
        const params = [];
        for (let j = i + 1; j < arrowIndex - 1; j += 1) {
          if (isIdent(tokens[j].value) && !KEYWORDS.has(tokens[j].value)) params.push({ name: tokens[j].value, tokenIndex: j });
        }
        return params;
      }
    }
  }
  return [];
}

function collectDeclarationsAndRefs(filePath, globalScope, projectGlobals, rootDeclarations) {
  const source = fs.readFileSync(filePath, "utf8");
  const tokens = tokenize(source);
  const fileRoot = makeScope(globalScope, "root", filePath);
  globalScope.children.push(fileRoot);
  let scope = fileRoot;
  const scopeStack = [fileRoot];
  let pendingFunctionParams = null;
  let pendingFunctionParamEndIndex = -1;
  let pendingClassBody = false;
  let declarationMode = null;
  let declarationDepth = 0;
  let declarationExpectName = false;
  let skipRefs = new Set();

  function pushScope(kind, params) {
    const child = makeScope(scope, kind, filePath);
    scope.children.push(child);
    scopeStack.push(child);
    scope = child;
    for (const param of params || []) declare(scope, param);
  }

  function popScope() {
    if (scopeStack.length > 1) {
      scopeStack.pop();
      scope = scopeStack[scopeStack.length - 1];
    }
  }

  for (let i = 0; i < tokens.length; i += 1) {
    const token = tokens[i];
    const value = token.value;
    const prev = tokens[i - 1] && tokens[i - 1].value;
    const next = tokens[i + 1] && tokens[i + 1].value;

    if (value === "{") {
      if (pendingClassBody) {
        pushScope("class", []);
        pendingClassBody = false;
      } else if (pendingFunctionParams && i > pendingFunctionParamEndIndex) {
        pushScope("function", pendingFunctionParams);
        pendingFunctionParams = null;
        pendingFunctionParamEndIndex = -1;
      } else {
        pushScope("block", []);
      }
      declarationMode = null;
      continue;
    }
    if (value === "}") {
      popScope();
      declarationMode = null;
      continue;
    }

    if (value === "function") {
      const nameTok = tokens[i + 1];
      if (nameTok && isIdent(nameTok.value)) {
        declare(scope, nameTok.value);
        if (scope.kind === "root") projectGlobals.add(nameTok.value);
        skipRefs.add(i + 1);
      }
      const parenIndex = tokens.findIndex((tok, idx) => idx > i && tok.value === "(");
      if (parenIndex !== -1) {
        const parsed = parseParamNames(tokens, parenIndex);
        pendingFunctionParams = parsed.params;
        pendingFunctionParamEndIndex = parsed.end;
        for (const idx of parsed.paramIndices) skipRefs.add(idx);
      }
      continue;
    }

    if (value === "catch" && next === "(") {
      const nameTok = tokens[i + 2];
      if (nameTok && isIdent(nameTok.value)) {
        pendingFunctionParams = [nameTok.value];
        pendingFunctionParamEndIndex = i + 3;
        skipRefs.add(i + 2);
      }
      continue;
    }

    if (next === "=>") {
      skipRefs.add(i);
      continue;
    }

    if (value === "=>") {
      const params = arrowParamsBefore(tokens, i);
      const paramNames = params.map((param) => param.name);
      const paramIndexes = new Set(params.map((param) => tokens[param.tokenIndex].index));
      for (const param of params) skipRefs.add(param.tokenIndex);
      scope.refs = scope.refs.filter((ref) => !paramIndexes.has(ref.index));
      if (next === "{") {
        pendingFunctionParams = paramNames;
        pendingFunctionParamEndIndex = i;
      } else {
        for (const param of paramNames) declare(scope, param);
      }
      continue;
    }

    if ((value === "var" || value === "let" || value === "const")) {
      declarationMode = value;
      declarationDepth = 0;
      declarationExpectName = true;
      continue;
    }

    if (declarationMode) {
      if (value === "(" || value === "[" || value === "{") declarationDepth += 1;
      if (value === ")" || value === "]" || value === "}") declarationDepth -= 1;
      if ((value === ";" || value === "for") && declarationDepth <= 0) {
        declarationMode = null;
        declarationExpectName = false;
        continue;
      }
      if (value === "," && declarationDepth === 0) {
        declarationExpectName = true;
        continue;
      }
      if (value === "=" && declarationDepth === 0) {
        declarationExpectName = false;
        continue;
      }
      if (declarationExpectName && isIdent(value) && !KEYWORDS.has(value) && declarationDepth === 0 && prev !== "." && next !== ":") {
        const targetScope = declarationMode === "var" ? nearestFunctionScope(scope) : scope;
        declare(targetScope, value);
        if (targetScope.kind === "root") {
          projectGlobals.add(value);
          if (declarationMode === "let" || declarationMode === "const") {
            if (!rootDeclarations.has(value)) rootDeclarations.set(value, []);
            rootDeclarations.get(value).push({ kind: declarationMode, file: filePath, line: token.line, column: token.column });
          }
        }
        skipRefs.add(i);
        declarationExpectName = false;
        continue;
      }
      continue;
    }

    if (value === "class" && next && isIdent(next)) {
      declare(scope, next);
      if (scope.kind === "root") {
        projectGlobals.add(next);
        if (!rootDeclarations.has(next)) rootDeclarations.set(next, []);
        rootDeclarations.get(next).push({ kind: "class", file: filePath, line: token.line, column: token.column });
      }
      skipRefs.add(i + 1);
      pendingClassBody = true;
      continue;
    }

    if (scope.kind === "class" && isIdent(value) && next === "(") {
      const parsed = parseParamNames(tokens, i + 1);
      pendingFunctionParams = parsed.params;
      pendingFunctionParamEndIndex = parsed.end;
      skipRefs.add(i);
      for (const idx of parsed.paramIndices) skipRefs.add(idx);
      continue;
    }

    if (scope.kind === "class" && (value === "get" || value === "set") && tokens[i + 2] && tokens[i + 2].value === "(") {
      const parsed = parseParamNames(tokens, i + 2);
      pendingFunctionParams = parsed.params;
      pendingFunctionParamEndIndex = parsed.end;
      skipRefs.add(i);
      skipRefs.add(i + 1);
      for (const idx of parsed.paramIndices) skipRefs.add(idx);
      continue;
    }

    if ((value === "window" || value === "globalThis" || value === "root") && next === "." && tokens[i + 2] && isIdent(tokens[i + 2].value)) {
      const afterProp = tokens[i + 3] && tokens[i + 3].value;
      if (afterProp === "=") projectGlobals.add(tokens[i + 2].value);
    }

    if (!isIdent(value) || KEYWORDS.has(value) || skipRefs.has(i)) continue;
    if (prev === ".") continue;
    if (next === ":" && prev !== "?") continue;
    if (prev === ":" && tokens[i - 2] && tokens[i - 2].value === "?") continue;
    scope.refs.push(token);
  }
}

function resolveRef(scope, name, projectGlobals) {
  if (KNOWN_GLOBALS.has(name) || projectGlobals.has(name)) return true;
  let current = scope;
  while (current) {
    if (current.declarations.has(name)) return true;
    current = current.parent;
  }
  return false;
}

function collectUnresolved(scope, projectGlobals, errors) {
  for (const ref of scope.refs) {
    if (!resolveRef(scope, ref.value, projectGlobals)) {
      errors.push(`${path.relative(ROOT, scope.file)}:${ref.line}:${ref.column} '${ref.value}' is not defined`);
    }
  }
  for (const child of scope.children) collectUnresolved(child, projectGlobals, errors);
}

function jsFilesForEval(evalDir) {
  const previewNames = ["index.html", "elevator_sim.html", "elevator_simulation.html", "test.html"];
  for (const previewName of previewNames) {
    const previewPath = path.join(evalDir, previewName);
    if (!fs.existsSync(previewPath)) continue;
    const html = fs.readFileSync(previewPath, "utf8");
    const scripts = [];
    const scriptRe = /<script\b[^>]*\bsrc\s*=\s*["']([^"']+)["'][^>]*>\s*<\/script>/gi;
    let match;
    while ((match = scriptRe.exec(html))) {
      const src = match[1];
      const lower = src.toLowerCase();
      if (lower.includes("://") || lower.startsWith("data:") || lower.startsWith("about:")) continue;
      if (src.startsWith("/") || src.startsWith("\\")) continue;
      const scriptPath = path.resolve(evalDir, src);
      if (!scriptPath.startsWith(path.resolve(evalDir))) continue;
      if (fs.existsSync(scriptPath) && scriptPath.toLowerCase().endsWith(".js")) {
        scripts.push(scriptPath);
      }
    }
    if (scripts.length) return Array.from(new Set(scripts));
  }
  return fs.readdirSync(evalDir)
    .filter((name) => name.toLowerCase().endsWith(".js"))
    .filter((name) => !name.toLowerCase().endsWith("_test.js"))
    .map((name) => path.join(evalDir, name));
}

function readIfExists(filePath) {
  if (!fs.existsSync(filePath)) return "";
  return fs.readFileSync(filePath, "utf8");
}

function stripForContract(source) {
  return stripStringsAndComments(source);
}

function checkElevatorContract(evalDir) {
  const errors = [];
  if (!path.basename(evalDir).includes("elevator_prompt_wiggum")) return errors;

  const indexPath = path.join(evalDir, "index.html");
  const personPath = path.join(evalDir, "person.js");
  const elevatorPath = path.join(evalDir, "elevator.js");
  const hasElevatorFiles = [indexPath, personPath, elevatorPath].some((filePath) => fs.existsSync(filePath));
  if (!hasElevatorFiles) return errors;

  for (const filePath of [indexPath, personPath, elevatorPath]) {
    if (!fs.existsSync(filePath)) {
      errors.push(`${path.relative(ROOT, filePath)}: required elevator artifact is missing`);
    }
  }
  if (errors.length) return errors;

  const index = readIfExists(indexPath);
  const person = readIfExists(personPath);
  const elevator = readIfExists(elevatorPath);
  const allCode = `${index}\n${person}\n${elevator}`;
  const strippedPerson = stripForContract(person);
  const strippedElevator = stripForContract(elevator);

  const scriptSrcs = [];
  const scriptRe = /<script\b([^>]*)\bsrc\s*=\s*["']([^"']+)["']([^>]*)>\s*<\/script>/gi;
  let scriptMatch;
  while ((scriptMatch = scriptRe.exec(index))) {
    const attrs = `${scriptMatch[1]} ${scriptMatch[3]}`;
    scriptSrcs.push({ src: scriptMatch[2], attrs });
  }
  const expectedScripts = [
    "https://cdn.jsdelivr.net/npm/three@0.147.0/build/three.min.js",
    "https://cdn.jsdelivr.net/npm/three@0.147.0/examples/js/controls/OrbitControls.js",
    "person.js",
    "elevator.js",
  ];
  const actualScripts = scriptSrcs.map((item) => item.src);
  if (JSON.stringify(actualScripts) !== JSON.stringify(expectedScripts)) {
    errors.push(`${path.relative(ROOT, indexPath)}: script src order must exactly be Three 0.147.0, OrbitControls, person.js, elevator.js`);
  }
  for (const item of scriptSrcs) {
    if (/\btype\s*=\s*["']module["']/i.test(item.attrs)) {
      errors.push(`${path.relative(ROOT, indexPath)}: classic scripts required; remove type="module"`);
    }
  }
  const extraLocalScripts = actualScripts.filter((src) => !src.includes("://") && !["person.js", "elevator.js"].includes(src));
  if (extraLocalScripts.length) {
    errors.push(`${path.relative(ROOT, indexPath)}: unexpected local script(s): ${extraLocalScripts.join(", ")}`);
  }

  const forbiddenPatterns = [
    [/\bimport\b/m, "import"],
    [/\bexport\b/m, "export"],
    [/\btype\s*=\s*["']module["']/im, "type=\"module\""],
    [/file:\/\//i, "file://"],
    [/summary\.html/i, "summary.html"],
    [/<\s*iframe\b/i, "<iframe"],
    [/<\s*object\b/i, "<object"],
    [/<\s*embed\b/i, "<embed"],
  ];
  for (const [pattern, label] of forbiddenPatterns) {
    if (pattern.test(allCode)) errors.push(`elevator contract: forbidden ${label} found`);
  }

  const requiredConstants = new Map([
    ["FLOOR_HEIGHT", "3"],
    ["FLOOR_COUNT", "6"],
    ["BUILDING_WIDTH", "20"],
    ["BUILDING_DEPTH", "15"],
    ["SHAFT_WIDTH", "5"],
    ["SHAFT_DEPTH", "5"],
    ["ELEVATOR_SPEED", "2"],
    ["PERSON_MOVE_SPEED", "1"],
  ]);
  for (const [name, value] of requiredConstants.entries()) {
    const re = new RegExp(`(^|\\n)\\s*const\\s+${name}\\s*=\\s*${value}\\s*;`);
    if (!re.test(strippedElevator)) {
      errors.push(`${path.relative(ROOT, elevatorPath)}: missing top-level "const ${name} = ${value};"`);
    }
  }

  const requiredGlobals = [
    ["scene", /(^|\n)\s*let\s+scene\s*;/],
    ["camera", /(^|\n)\s*let\s+camera\s*;/],
    ["renderer", /(^|\n)\s*let\s+renderer\s*;/],
    ["controls", /(^|\n)\s*let\s+controls\s*;/],
    ["elevatorCar", /(^|\n)\s*let\s+elevatorCar\s*;/],
    ["people", /(^|\n)\s*let\s+people\s*=\s*\[\s*\]\s*;/],
  ];
  for (const [name, pattern] of requiredGlobals) {
    if (!pattern.test(strippedElevator)) {
      errors.push(`${path.relative(ROOT, elevatorPath)}: missing required top-level global "let ${name}"`);
    }
  }

  for (const forbidden of ["scene", "camera", "renderer", "controls", "elevatorCar", "people"]) {
    const re = new RegExp(`(^|\\n)\\s*(?:let|const|var)\\s+${forbidden}\\b`);
    if (re.test(strippedPerson)) {
      errors.push(`${path.relative(ROOT, personPath)}: must not declare ${forbidden}`);
    }
  }
  if (!/(^|\n)\s*function\s+createPerson\s*\(\s*color\s*\)/.test(strippedPerson)) {
    errors.push(`${path.relative(ROOT, personPath)}: must define global function createPerson(color)`);
  }
  for (const required of ["leftLeg", "rightLeg", "isWalking"]) {
    if (!new RegExp(`\\b${required}\\b`).test(strippedPerson)) {
      errors.push(`${path.relative(ROOT, personPath)}: createPerson userData must include ${required}`);
    }
  }
  if (!/new\s+THREE\.Group\s*\(/.test(strippedPerson) || !/return\s+[A-Za-z_$][A-Za-z0-9_$]*\s*;/.test(strippedPerson)) {
    errors.push(`${path.relative(ROOT, personPath)}: createPerson must create and return a THREE.Group`);
  }

  if (!/new\s+THREE\.Group\s*\(/.test(strippedElevator) || !/elevatorCar\s*=/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: elevatorCar must be assigned a THREE.Group`);
  }
  if (!/elevatorCar\.leftDoor\s*=\s*leftDoor\s*;/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: must store left door as elevatorCar.leftDoor = leftDoor;`);
  }
  if (!/elevatorCar\.rightDoor\s*=\s*rightDoor\s*;/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: must store right door as elevatorCar.rightDoor = rightDoor;`);
  }
  if (!/elevatorCar\.attach\s*\(/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: boarding must use elevatorCar.attach(...) to preserve world position`);
  }
  if (!/scene\.attach\s*\(/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: exiting must use scene.attach(...) to preserve world position`);
  }
  if (/elevatorCar\.add\s*\(\s*person/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: do not use elevatorCar.add(person) for boarding`);
  }
  if (!/startSimulation\s*\(/.test(strippedElevator) || !/DOMContentLoaded/.test(elevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: must auto-start startSimulation with the DOMContentLoaded pattern`);
  }

  return errors;
}

function staticCheckEval(evalDir) {
  const jsFiles = jsFilesForEval(evalDir);
  const syntaxErrors = [];
  for (const filePath of jsFiles) {
    const result = spawnSync(process.execPath, ["--check", filePath], { encoding: "utf8" });
    if (result.status !== 0) {
      const relFile = path.relative(ROOT, filePath);
      const lines = (result.stderr || result.stdout || "")
        .trim()
        .split(/\r?\n/)
        .map((line) => line.trimEnd())
        .filter((line) => line && !line.startsWith("at ") && !line.startsWith("Node.js"));
      if (lines[0] && path.resolve(lines[0].split(":").slice(0, -1).join(":")) === filePath) {
        lines[0] = lines[0].replace(filePath, relFile);
      }
      const syntaxLineIndex = lines.findIndex((line) => /^SyntaxError\b/.test(line));
      const usefulLines = syntaxLineIndex >= 0 ? lines.slice(0, syntaxLineIndex + 1) : lines.slice(0, 4);
      const message = usefulLines.join(" | ");
      syntaxErrors.push(message || `${relFile}: syntax check failed`);
    }
  }

  const globalScope = makeScope(null, "global", "");
  const projectGlobals = new Set();
  const rootDeclarations = new Map();
  for (const filePath of jsFiles) collectDeclarationsAndRefs(filePath, globalScope, projectGlobals, rootDeclarations);

  const referenceErrors = [];
  for (const child of globalScope.children) collectUnresolved(child, projectGlobals, referenceErrors);
  const duplicateErrors = [];
  for (const [name, declarations] of rootDeclarations.entries()) {
    if (declarations.length < 2) continue;
    const locations = declarations
      .map((decl) => `${path.relative(ROOT, decl.file)}:${decl.line}:${decl.column}`)
      .join(", ");
    duplicateErrors.push(`Duplicate top-level lexical declaration '${name}' in classic scripts: ${locations}`);
  }
  const contractErrors = checkElevatorContract(evalDir);
  const staticErrors = [...syntaxErrors, ...duplicateErrors, ...referenceErrors, ...contractErrors];
  return {
    checked_at: new Date().toISOString(),
    files_checked: jsFiles.map((filePath) => path.relative(ROOT, filePath)),
    static_errors: Array.from(new Set(staticErrors)).slice(0, 30),
    static_warnings: [],
  };
}

function targets(arg) {
  if (!arg || arg === "--all") {
    if (!fs.existsSync(EVALS_DIR)) return [];
    return fs.readdirSync(EVALS_DIR)
      .map((name) => path.join(EVALS_DIR, name))
      .filter((item) => fs.statSync(item).isDirectory());
  }
  const direct = path.resolve(ROOT, arg);
  return fs.existsSync(direct) && fs.statSync(direct).isDirectory() ? [direct] : [];
}

if (require.main === module) {
  const dirs = targets(process.argv[2] || "--all");
  if (!dirs.length) {
    console.error("No evaluation directories found.");
    process.exit(1);
  }
  let hadErrors = false;
  for (const dir of dirs) {
    const result = staticCheckEval(dir);
    fs.writeFileSync(path.join(dir, "static_check.json"), `${JSON.stringify(result, null, 2)}\n`, "utf8");
    if (result.static_errors.length) hadErrors = true;
    const status = result.static_errors.length ? "errors" : "ok";
    console.log(`${path.relative(ROOT, dir)}: ${status}, static check written`);
    for (const err of result.static_errors.slice(0, 5)) {
      console.log(`  - ${err}`);
    }
  }
  process.exit(hadErrors ? 2 : 0);
}

module.exports = { staticCheckEval };

#!/usr/bin/env node
const fs = require("fs");
const path = require("path");
const { spawnSync } = require("child_process");

const ROOT = process.cwd();
const EVALS_DIR = path.join(ROOT, "evals");

const KEYWORDS = new Set([
  "await", "async", "break", "case", "catch", "class", "const", "continue",
  "debugger", "default", "delete", "do", "else", "export", "extends",
  "false", "finally", "for", "from", "function", "if", "import", "in", "instanceof",
  "let", "new", "null", "of", "return", "static", "super", "switch", "this",
  "throw", "try", "typeof", "var", "void", "while", "with", "yield",
  "true",
]);

const KNOWN_GLOBALS = new Set([
  "Array", "ArrayBuffer", "BigInt", "Boolean", "DataView", "Date", "Error",
  "EvalError", "Event", "Float32Array", "Float64Array", "Infinity", "Intl",
  "JSON", "Map", "Math", "NaN", "Number", "Object", "Promise", "Proxy",
  "RangeError", "ReferenceError", "Reflect", "RegExp", "Set", "String",
  "Symbol", "SyntaxError", "THREE", "TypeError", "URIError", "URL",
  "WeakMap", "WeakSet", "alert", "cancelAnimationFrame", "clearInterval",
  "clearTimeout", "console", "decodeURIComponent", "document",
  "encodeURIComponent", "fetch", "globalThis", "isFinite", "isNaN",
  "localStorage", "module", "parseFloat", "parseInt", "performance",
  "requestAnimationFrame", "setInterval", "setTimeout", "undefined", "window",
]);

function isIdent(value) {
  return /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(value);
}

function stripStringsAndComments(source) {
  let out = "";
  for (let i = 0; i < source.length;) {
    const ch = source[i];
    const next = source[i + 1];
    if (ch === "/" && next === "/") {
      out += "  ";
      i += 2;
      while (i < source.length && source[i] !== "\n") {
        out += " ";
        i += 1;
      }
      continue;
    }
    if (ch === "/" && next === "*") {
      out += "  ";
      i += 2;
      while (i < source.length && !(source[i] === "*" && source[i + 1] === "/")) {
        out += source[i] === "\n" ? "\n" : " ";
        i += 1;
      }
      if (i < source.length) {
        out += "  ";
        i += 2;
      }
      continue;
    }
    if (ch === "\"" || ch === "'" || ch === "`") {
      const quote = ch;
      out += " ";
      i += 1;
      while (i < source.length) {
        if (source[i] === "\\") {
          out += " ";
          i += 1;
          if (i < source.length) {
            out += source[i] === "\n" ? "\n" : " ";
            i += 1;
          }
          continue;
        }
        if (source[i] === quote) {
          out += " ";
          i += 1;
          break;
        }
        out += source[i] === "\n" ? "\n" : " ";
        i += 1;
      }
      continue;
    }
    out += ch;
    i += 1;
  }
  return out;
}

function tokenize(source) {
  const stripped = stripStringsAndComments(source);
  const tokens = [];
  const re = /0x[0-9A-Fa-f]+|\d+(?:\.\d+)?|[A-Za-z_$][A-Za-z0-9_$]*|=>|===|!==|==|!=|<=|>=|\+\+|--|&&|\|\||[{}()[\].,;:=+\-*/%<>!?]/g;
  const lineStarts = [0];
  for (let i = 0; i < stripped.length; i += 1) {
    if (stripped[i] === "\n") lineStarts.push(i + 1);
  }
  function position(index) {
    let lo = 0;
    let hi = lineStarts.length - 1;
    while (lo <= hi) {
      const mid = Math.floor((lo + hi) / 2);
      if (lineStarts[mid] <= index) lo = mid + 1;
      else hi = mid - 1;
    }
    const lineIndex = Math.max(0, hi);
    return { line: lineIndex + 1, column: index - lineStarts[lineIndex] + 1 };
  }
  let match;
  while ((match = re.exec(stripped))) {
    tokens.push({ value: match[0], index: match.index, ...position(match.index) });
  }
  return tokens;
}

function makeScope(parent, kind, file) {
  return { parent, kind, file, declarations: new Set(), refs: [], children: [] };
}

function declare(scope, name) {
  if (name && isIdent(name) && !KEYWORDS.has(name)) scope.declarations.add(name);
}

function nearestFunctionScope(scope) {
  let current = scope;
  while (current && current.kind !== "function" && current.kind !== "root") {
    current = current.parent;
  }
  return current || scope;
}

function parseParamNames(tokens, startIndex) {
  const params = [];
  const paramIndices = [];
  let depth = 0;
  for (let i = startIndex; i < tokens.length; i += 1) {
    const value = tokens[i].value;
    if (value === "(") {
      depth += 1;
      continue;
    }
    if (value === ")") {
      depth -= 1;
      if (depth === 0) return { params, paramIndices, end: i };
      continue;
    }
    if (depth === 1 && isIdent(value) && !KEYWORDS.has(value)) {
      params.push(value);
      paramIndices.push(i);
    }
  }
  return { params, paramIndices, end: startIndex };
}

function arrowParamsBefore(tokens, arrowIndex) {
  const prev = tokens[arrowIndex - 1];
  if (!prev) return [];
  if (isIdent(prev.value) && !KEYWORDS.has(prev.value)) return [{ name: prev.value, tokenIndex: arrowIndex - 1 }];
  if (prev.value !== ")") return [];
  let depth = 0;
  for (let i = arrowIndex - 1; i >= 0; i -= 1) {
    const value = tokens[i].value;
    if (value === ")") depth += 1;
    else if (value === "(") {
      depth -= 1;
      if (depth === 0) {
        const params = [];
        for (let j = i + 1; j < arrowIndex - 1; j += 1) {
          if (isIdent(tokens[j].value) && !KEYWORDS.has(tokens[j].value)) params.push({ name: tokens[j].value, tokenIndex: j });
        }
        return params;
      }
    }
  }
  return [];
}

function collectDeclarationsAndRefs(filePath, globalScope, projectGlobals, rootDeclarations) {
  const source = fs.readFileSync(filePath, "utf8");
  const tokens = tokenize(source);
  const fileRoot = makeScope(globalScope, "root", filePath);
  globalScope.children.push(fileRoot);
  let scope = fileRoot;
  const scopeStack = [fileRoot];
  let pendingFunctionParams = null;
  let pendingFunctionParamEndIndex = -1;
  let pendingClassBody = false;
  let declarationMode = null;
  let declarationDepth = 0;
  let declarationExpectName = false;
  let skipRefs = new Set();

  function pushScope(kind, params) {
    const child = makeScope(scope, kind, filePath);
    scope.children.push(child);
    scopeStack.push(child);
    scope = child;
    for (const param of params || []) declare(scope, param);
  }

  function popScope() {
    if (scopeStack.length > 1) {
      scopeStack.pop();
      scope = scopeStack[scopeStack.length - 1];
    }
  }

  for (let i = 0; i < tokens.length; i += 1) {
    const token = tokens[i];
    const value = token.value;
    const prev = tokens[i - 1] && tokens[i - 1].value;
    const next = tokens[i + 1] && tokens[i + 1].value;

    if (value === "{") {
      if (pendingClassBody) {
        pushScope("class", []);
        pendingClassBody = false;
      } else if (pendingFunctionParams && i > pendingFunctionParamEndIndex) {
        pushScope("function", pendingFunctionParams);
        pendingFunctionParams = null;
        pendingFunctionParamEndIndex = -1;
      } else {
        pushScope("block", []);
      }
      declarationMode = null;
      continue;
    }
    if (value === "}") {
      popScope();
      declarationMode = null;
      continue;
    }

    if (value === "function") {
      const nameTok = tokens[i + 1];
      if (nameTok && isIdent(nameTok.value)) {
        declare(scope, nameTok.value);
        if (scope.kind === "root") projectGlobals.add(nameTok.value);
        skipRefs.add(i + 1);
      }
      const parenIndex = tokens.findIndex((tok, idx) => idx > i && tok.value === "(");
      if (parenIndex !== -1) {
        const parsed = parseParamNames(tokens, parenIndex);
        pendingFunctionParams = parsed.params;
        pendingFunctionParamEndIndex = parsed.end;
        for (const idx of parsed.paramIndices) skipRefs.add(idx);
      }
      continue;
    }

    if (value === "catch" && next === "(") {
      const nameTok = tokens[i + 2];
      if (nameTok && isIdent(nameTok.value)) {
        pendingFunctionParams = [nameTok.value];
        pendingFunctionParamEndIndex = i + 3;
        skipRefs.add(i + 2);
      }
      continue;
    }

    if (next === "=>") {
      skipRefs.add(i);
      continue;
    }

    if (value === "=>") {
      const params = arrowParamsBefore(tokens, i);
      const paramNames = params.map((param) => param.name);
      const paramIndexes = new Set(params.map((param) => tokens[param.tokenIndex].index));
      for (const param of params) skipRefs.add(param.tokenIndex);
      scope.refs = scope.refs.filter((ref) => !paramIndexes.has(ref.index));
      if (next === "{") {
        pendingFunctionParams = paramNames;
        pendingFunctionParamEndIndex = i;
      } else {
        for (const param of paramNames) declare(scope, param);
      }
      continue;
    }

    if ((value === "var" || value === "let" || value === "const")) {
      declarationMode = value;
      declarationDepth = 0;
      declarationExpectName = true;
      continue;
    }

    if (declarationMode) {
      if (value === "(" || value === "[" || value === "{") declarationDepth += 1;
      if (value === ")" || value === "]" || value === "}") declarationDepth -= 1;
      if ((value === ";" || value === "for") && declarationDepth <= 0) {
        declarationMode = null;
        declarationExpectName = false;
        continue;
      }
      if (value === "," && declarationDepth === 0) {
        declarationExpectName = true;
        continue;
      }
      if (value === "=" && declarationDepth === 0) {
        declarationExpectName = false;
        continue;
      }
      if (declarationExpectName && isIdent(value) && !KEYWORDS.has(value) && declarationDepth === 0 && prev !== "." && next !== ":") {
        const targetScope = declarationMode === "var" ? nearestFunctionScope(scope) : scope;
        declare(targetScope, value);
        if (targetScope.kind === "root") {
          projectGlobals.add(value);
          if (declarationMode === "let" || declarationMode === "const") {
            if (!rootDeclarations.has(value)) rootDeclarations.set(value, []);
            rootDeclarations.get(value).push({ kind: declarationMode, file: filePath, line: token.line, column: token.column });
          }
        }
        skipRefs.add(i);
        declarationExpectName = false;
        continue;
      }
      continue;
    }

    if (value === "class" && next && isIdent(next)) {
      declare(scope, next);
      if (scope.kind === "root") {
        projectGlobals.add(next);
        if (!rootDeclarations.has(next)) rootDeclarations.set(next, []);
        rootDeclarations.get(next).push({ kind: "class", file: filePath, line: token.line, column: token.column });
      }
      skipRefs.add(i + 1);
      pendingClassBody = true;
      continue;
    }

    if (scope.kind === "class" && isIdent(value) && next === "(") {
      const parsed = parseParamNames(tokens, i + 1);
      pendingFunctionParams = parsed.params;
      pendingFunctionParamEndIndex = parsed.end;
      skipRefs.add(i);
      for (const idx of parsed.paramIndices) skipRefs.add(idx);
      continue;
    }

    if (scope.kind === "class" && (value === "get" || value === "set") && tokens[i + 2] && tokens[i + 2].value === "(") {
      const parsed = parseParamNames(tokens, i + 2);
      pendingFunctionParams = parsed.params;
      pendingFunctionParamEndIndex = parsed.end;
      skipRefs.add(i);
      skipRefs.add(i + 1);
      for (const idx of parsed.paramIndices) skipRefs.add(idx);
      continue;
    }

    if ((value === "window" || value === "globalThis" || value === "root") && next === "." && tokens[i + 2] && isIdent(tokens[i + 2].value)) {
      const afterProp = tokens[i + 3] && tokens[i + 3].value;
      if (afterProp === "=") projectGlobals.add(tokens[i + 2].value);
    }

    if (!isIdent(value) || KEYWORDS.has(value) || skipRefs.has(i)) continue;
    if (prev === ".") continue;
    if (next === ":" && prev !== "?") continue;
    if (prev === ":" && tokens[i - 2] && tokens[i - 2].value === "?") continue;
    scope.refs.push(token);
  }
}

function resolveRef(scope, name, projectGlobals) {
  if (KNOWN_GLOBALS.has(name) || projectGlobals.has(name)) return true;
  let current = scope;
  while (current) {
    if (current.declarations.has(name)) return true;
    current = current.parent;
  }
  return false;
}

function collectUnresolved(scope, projectGlobals, errors) {
  for (const ref of scope.refs) {
    if (!resolveRef(scope, ref.value, projectGlobals)) {
      errors.push(`${path.relative(ROOT, scope.file)}:${ref.line}:${ref.column} '${ref.value}' is not defined`);
    }
  }
  for (const child of scope.children) collectUnresolved(child, projectGlobals, errors);
}

function jsFilesForEval(evalDir) {
  const previewNames = ["index.html", "elevator_sim.html", "elevator_simulation.html", "test.html"];
  for (const previewName of previewNames) {
    const previewPath = path.join(evalDir, previewName);
    if (!fs.existsSync(previewPath)) continue;
    const html = fs.readFileSync(previewPath, "utf8");
    const scripts = [];
    const scriptRe = /<script\b[^>]*\bsrc\s*=\s*["']([^"']+)["'][^>]*>\s*<\/script>/gi;
    let match;
    while ((match = scriptRe.exec(html))) {
      const src = match[1];
      const lower = src.toLowerCase();
      if (lower.includes("://") || lower.startsWith("data:") || lower.startsWith("about:")) continue;
      if (src.startsWith("/") || src.startsWith("\\")) continue;
      const scriptPath = path.resolve(evalDir, src);
      if (!scriptPath.startsWith(path.resolve(evalDir))) continue;
      if (fs.existsSync(scriptPath) && scriptPath.toLowerCase().endsWith(".js")) {
        scripts.push(scriptPath);
      }
    }
    if (scripts.length) return Array.from(new Set(scripts));
  }
  return fs.readdirSync(evalDir)
    .filter((name) => name.toLowerCase().endsWith(".js"))
    .filter((name) => !name.toLowerCase().endsWith("_test.js"))
    .map((name) => path.join(evalDir, name));
}

function readIfExists(filePath) {
  if (!fs.existsSync(filePath)) return "";
  return fs.readFileSync(filePath, "utf8");
}

function stripForContract(source) {
  return stripStringsAndComments(source);
}

function checkElevatorContract(evalDir) {
  const errors = [];
  if (!path.basename(evalDir).includes("elevator_prompt_wiggum")) return errors;

  const indexPath = path.join(evalDir, "index.html");
  const personPath = path.join(evalDir, "person.js");
  const elevatorPath = path.join(evalDir, "elevator.js");
  const hasElevatorFiles = [indexPath, personPath, elevatorPath].some((filePath) => fs.existsSync(filePath));
  if (!hasElevatorFiles) return errors;

  for (const filePath of [indexPath, personPath, elevatorPath]) {
    if (!fs.existsSync(filePath)) {
      errors.push(`${path.relative(ROOT, filePath)}: required elevator artifact is missing`);
    }
  }
  if (errors.length) return errors;

  const index = readIfExists(indexPath);
  const person = readIfExists(personPath);
  const elevator = readIfExists(elevatorPath);
  const allCode = `${index}\n${person}\n${elevator}`;
  const strippedPerson = stripForContract(person);
  const strippedElevator = stripForContract(elevator);

  const scriptSrcs = [];
  const scriptRe = /<script\b([^>]*)\bsrc\s*=\s*["']([^"']+)["']([^>]*)>\s*<\/script>/gi;
  let scriptMatch;
  while ((scriptMatch = scriptRe.exec(index))) {
    const attrs = `${scriptMatch[1]} ${scriptMatch[3]}`;
    scriptSrcs.push({ src: scriptMatch[2], attrs });
  }
  const expectedScripts = [
    "https://cdn.jsdelivr.net/npm/three@0.147.0/build/three.min.js",
    "https://cdn.jsdelivr.net/npm/three@0.147.0/examples/js/controls/OrbitControls.js",
    "person.js",
    "elevator.js",
  ];
  const actualScripts = scriptSrcs.map((item) => item.src);
  if (JSON.stringify(actualScripts) !== JSON.stringify(expectedScripts)) {
    errors.push(`${path.relative(ROOT, indexPath)}: script src order must exactly be Three 0.147.0, OrbitControls, person.js, elevator.js`);
  }
  for (const item of scriptSrcs) {
    if (/\btype\s*=\s*["']module["']/i.test(item.attrs)) {
      errors.push(`${path.relative(ROOT, indexPath)}: classic scripts required; remove type="module"`);
    }
  }
  const extraLocalScripts = actualScripts.filter((src) => !src.includes("://") && !["person.js", "elevator.js"].includes(src));
  if (extraLocalScripts.length) {
    errors.push(`${path.relative(ROOT, indexPath)}: unexpected local script(s): ${extraLocalScripts.join(", ")}`);
  }

  const forbiddenPatterns = [
    [/\bimport\b/m, "import"],
    [/\bexport\b/m, "export"],
    [/\btype\s*=\s*["']module["']/im, "type=\"module\""],
    [/file:\/\//i, "file://"],
    [/summary\.html/i, "summary.html"],
    [/<\s*iframe\b/i, "<iframe"],
    [/<\s*object\b/i, "<object"],
    [/<\s*embed\b/i, "<embed"],
  ];
  for (const [pattern, label] of forbiddenPatterns) {
    if (pattern.test(allCode)) errors.push(`elevator contract: forbidden ${label} found`);
  }

  const requiredConstants = new Map([
    ["FLOOR_HEIGHT", "3"],
    ["FLOOR_COUNT", "6"],
    ["BUILDING_WIDTH", "20"],
    ["BUILDING_DEPTH", "15"],
    ["SHAFT_WIDTH", "5"],
    ["SHAFT_DEPTH", "5"],
    ["ELEVATOR_SPEED", "2"],
    ["PERSON_MOVE_SPEED", "1"],
  ]);
  for (const [name, value] of requiredConstants.entries()) {
    const re = new RegExp(`(^|\\n)\\s*const\\s+${name}\\s*=\\s*${value}\\s*;`);
    if (!re.test(strippedElevator)) {
      errors.push(`${path.relative(ROOT, elevatorPath)}: missing top-level "const ${name} = ${value};"`);
    }
  }

  const requiredGlobals = [
    ["scene", /(^|\n)\s*let\s+scene\s*;/],
    ["camera", /(^|\n)\s*let\s+camera\s*;/],
    ["renderer", /(^|\n)\s*let\s+renderer\s*;/],
    ["controls", /(^|\n)\s*let\s+controls\s*;/],
    ["elevatorCar", /(^|\n)\s*let\s+elevatorCar\s*;/],
    ["people", /(^|\n)\s*let\s+people\s*=\s*\[\s*\]\s*;/],
  ];
  for (const [name, pattern] of requiredGlobals) {
    if (!pattern.test(strippedElevator)) {
      errors.push(`${path.relative(ROOT, elevatorPath)}: missing required top-level global "let ${name}"`);
    }
  }

  for (const forbidden of ["scene", "camera", "renderer", "controls", "elevatorCar", "people"]) {
    const re = new RegExp(`(^|\\n)\\s*(?:let|const|var)\\s+${forbidden}\\b`);
    if (re.test(strippedPerson)) {
      errors.push(`${path.relative(ROOT, personPath)}: must not declare ${forbidden}`);
    }
  }
  if (!/(^|\n)\s*function\s+createPerson\s*\(\s*color\s*\)/.test(strippedPerson)) {
    errors.push(`${path.relative(ROOT, personPath)}: must define global function createPerson(color)`);
  }
  for (const required of ["leftLeg", "rightLeg", "isWalking"]) {
    if (!new RegExp(`\\b${required}\\b`).test(strippedPerson)) {
      errors.push(`${path.relative(ROOT, personPath)}: createPerson userData must include ${required}`);
    }
  }
  if (!/new\s+THREE\.Group\s*\(/.test(strippedPerson) || !/return\s+[A-Za-z_$][A-Za-z0-9_$]*\s*;/.test(strippedPerson)) {
    errors.push(`${path.relative(ROOT, personPath)}: createPerson must create and return a THREE.Group`);
  }

  if (!/new\s+THREE\.Group\s*\(/.test(strippedElevator) || !/elevatorCar\s*=/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: elevatorCar must be assigned a THREE.Group`);
  }
  if (!/elevatorCar\.leftDoor\s*=\s*leftDoor\s*;/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: must store left door as elevatorCar.leftDoor = leftDoor;`);
  }
  if (!/elevatorCar\.rightDoor\s*=\s*rightDoor\s*;/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: must store right door as elevatorCar.rightDoor = rightDoor;`);
  }
  if (!/elevatorCar\.attach\s*\(/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: boarding must use elevatorCar.attach(...) to preserve world position`);
  }
  if (!/scene\.attach\s*\(/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: exiting must use scene.attach(...) to preserve world position`);
  }
  if (/elevatorCar\.add\s*\(\s*person/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: do not use elevatorCar.add(person) for boarding`);
  }
  if (!/startSimulation\s*\(/.test(strippedElevator) || !/DOMContentLoaded/.test(elevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: must auto-start startSimulation with the DOMContentLoaded pattern`);
  }

  return errors;
}

function staticCheckEval(evalDir) {
  const jsFiles = jsFilesForEval(evalDir);
  const syntaxErrors = [];
  for (const filePath of jsFiles) {
    const result = spawnSync(process.execPath, ["--check", filePath], { encoding: "utf8" });
    if (result.status !== 0) {
      const relFile = path.relative(ROOT, filePath);
      const lines = (result.stderr || result.stdout || "")
        .trim()
        .split(/\r?\n/)
        .map((line) => line.trimEnd())
        .filter((line) => line && !line.startsWith("at ") && !line.startsWith("Node.js"));
      if (lines[0] && path.resolve(lines[0].split(":").slice(0, -1).join(":")) === filePath) {
        lines[0] = lines[0].replace(filePath, relFile);
      }
      const syntaxLineIndex = lines.findIndex((line) => /^SyntaxError\b/.test(line));
      const usefulLines = syntaxLineIndex >= 0 ? lines.slice(0, syntaxLineIndex + 1) : lines.slice(0, 4);
      const message = usefulLines.join(" | ");
      syntaxErrors.push(message || `${relFile}: syntax check failed`);
    }
  }

  const globalScope = makeScope(null, "global", "");
  const projectGlobals = new Set();
  const rootDeclarations = new Map();
  for (const filePath of jsFiles) collectDeclarationsAndRefs(filePath, globalScope, projectGlobals, rootDeclarations);

  const referenceErrors = [];
  for (const child of globalScope.children) collectUnresolved(child, projectGlobals, referenceErrors);
  const duplicateErrors = [];
  for (const [name, declarations] of rootDeclarations.entries()) {
    if (declarations.length < 2) continue;
    const locations = declarations
      .map((decl) => `${path.relative(ROOT, decl.file)}:${decl.line}:${decl.column}`)
      .join(", ");
    duplicateErrors.push(`Duplicate top-level lexical declaration '${name}' in classic scripts: ${locations}`);
  }
  const contractErrors = checkElevatorContract(evalDir);
  const staticErrors = [...syntaxErrors, ...duplicateErrors, ...referenceErrors, ...contractErrors];
  return {
    checked_at: new Date().toISOString(),
    files_checked: jsFiles.map((filePath) => path.relative(ROOT, filePath)),
    static_errors: Array.from(new Set(staticErrors)).slice(0, 30),
    static_warnings: [],
  };
}

function targets(arg) {
  if (!arg || arg === "--all") {
    if (!fs.existsSync(EVALS_DIR)) return [];
    return fs.readdirSync(EVALS_DIR)
      .map((name) => path.join(EVALS_DIR, name))
      .filter((item) => fs.statSync(item).isDirectory());
  }
  const direct = path.resolve(ROOT, arg);
  return fs.existsSync(direct) && fs.statSync(direct).isDirectory() ? [direct] : [];
}

if (require.main === module) {
  const dirs = targets(process.argv[2] || "--all");
  if (!dirs.length) {
    console.error("No evaluation directories found.");
    process.exit(1);
  }
  let hadErrors = false;
  for (const dir of dirs) {
    const result = staticCheckEval(dir);
    fs.writeFileSync(path.join(dir, "static_check.json"), `${JSON.stringify(result, null, 2)}\n`, "utf8");
    if (result.static_errors.length) hadErrors = true;
    const status = result.static_errors.length ? "errors" : "ok";
    console.log(`${path.relative(ROOT, dir)}: ${status}, static check written`);
    for (const err of result.static_errors.slice(0, 5)) {
      console.log(`  - ${err}`);
    }
  }
  process.exit(hadErrors ? 2 : 0);
}

module.exports = { staticCheckEval };

#!/usr/bin/env node
const fs = require("fs");
const path = require("path");
const { spawnSync } = require("child_process");

const ROOT = process.cwd();
const EVALS_DIR = path.join(ROOT, "evals");

const KEYWORDS = new Set([
  "await", "async", "break", "case", "catch", "class", "const", "continue",
  "debugger", "default", "delete", "do", "else", "export", "extends",
  "false", "finally", "for", "from", "function", "if", "import", "in", "instanceof",
  "let", "new", "null", "of", "return", "static", "super", "switch", "this",
  "throw", "try", "typeof", "var", "void", "while", "with", "yield",
  "true",
]);

const KNOWN_GLOBALS = new Set([
  "Array", "ArrayBuffer", "BigInt", "Boolean", "DataView", "Date", "Error",
  "EvalError", "Event", "Float32Array", "Float64Array", "Infinity", "Intl",
  "JSON", "Map", "Math", "NaN", "Number", "Object", "Promise", "Proxy",
  "RangeError", "ReferenceError", "Reflect", "RegExp", "Set", "String",
  "Symbol", "SyntaxError", "THREE", "TypeError", "URIError", "URL",
  "WeakMap", "WeakSet", "alert", "cancelAnimationFrame", "clearInterval",
  "clearTimeout", "console", "decodeURIComponent", "document",
  "encodeURIComponent", "fetch", "globalThis", "isFinite", "isNaN",
  "localStorage", "module", "parseFloat", "parseInt", "performance",
  "requestAnimationFrame", "setInterval", "setTimeout", "undefined", "window",
]);

function isIdent(value) {
  return /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(value);
}

function stripStringsAndComments(source) {
  let out = "";
  for (let i = 0; i < source.length;) {
    const ch = source[i];
    const next = source[i + 1];
    if (ch === "/" && next === "/") {
      out += "  ";
      i += 2;
      while (i < source.length && source[i] !== "\n") {
        out += " ";
        i += 1;
      }
      continue;
    }
    if (ch === "/" && next === "*") {
      out += "  ";
      i += 2;
      while (i < source.length && !(source[i] === "*" && source[i + 1] === "/")) {
        out += source[i] === "\n" ? "\n" : " ";
        i += 1;
      }
      if (i < source.length) {
        out += "  ";
        i += 2;
      }
      continue;
    }
    if (ch === "\"" || ch === "'" || ch === "`") {
      const quote = ch;
      out += " ";
      i += 1;
      while (i < source.length) {
        if (source[i] === "\\") {
          out += " ";
          i += 1;
          if (i < source.length) {
            out += source[i] === "\n" ? "\n" : " ";
            i += 1;
          }
          continue;
        }
        if (source[i] === quote) {
          out += " ";
          i += 1;
          break;
        }
        out += source[i] === "\n" ? "\n" : " ";
        i += 1;
      }
      continue;
    }
    out += ch;
    i += 1;
  }
  return out;
}

function tokenize(source) {
  const stripped = stripStringsAndComments(source);
  const tokens = [];
  const re = /0x[0-9A-Fa-f]+|\d+(?:\.\d+)?|[A-Za-z_$][A-Za-z0-9_$]*|=>|===|!==|==|!=|<=|>=|\+\+|--|&&|\|\||[{}()[\].,;:=+\-*/%<>!?]/g;
  const lineStarts = [0];
  for (let i = 0; i < stripped.length; i += 1) {
    if (stripped[i] === "\n") lineStarts.push(i + 1);
  }
  function position(index) {
    let lo = 0;
    let hi = lineStarts.length - 1;
    while (lo <= hi) {
      const mid = Math.floor((lo + hi) / 2);
      if (lineStarts[mid] <= index) lo = mid + 1;
      else hi = mid - 1;
    }
    const lineIndex = Math.max(0, hi);
    return { line: lineIndex + 1, column: index - lineStarts[lineIndex] + 1 };
  }
  let match;
  while ((match = re.exec(stripped))) {
    tokens.push({ value: match[0], index: match.index, ...position(match.index) });
  }
  return tokens;
}

function makeScope(parent, kind, file) {
  return { parent, kind, file, declarations: new Set(), refs: [], children: [] };
}

function declare(scope, name) {
  if (name && isIdent(name) && !KEYWORDS.has(name)) scope.declarations.add(name);
}

function nearestFunctionScope(scope) {
  let current = scope;
  while (current && current.kind !== "function" && current.kind !== "root") {
    current = current.parent;
  }
  return current || scope;
}

function parseParamNames(tokens, startIndex) {
  const params = [];
  const paramIndices = [];
  let depth = 0;
  for (let i = startIndex; i < tokens.length; i += 1) {
    const value = tokens[i].value;
    if (value === "(") {
      depth += 1;
      continue;
    }
    if (value === ")") {
      depth -= 1;
      if (depth === 0) return { params, paramIndices, end: i };
      continue;
    }
    if (depth === 1 && isIdent(value) && !KEYWORDS.has(value)) {
      params.push(value);
      paramIndices.push(i);
    }
  }
  return { params, paramIndices, end: startIndex };
}

function arrowParamsBefore(tokens, arrowIndex) {
  const prev = tokens[arrowIndex - 1];
  if (!prev) return [];
  if (isIdent(prev.value) && !KEYWORDS.has(prev.value)) return [{ name: prev.value, tokenIndex: arrowIndex - 1 }];
  if (prev.value !== ")") return [];
  let depth = 0;
  for (let i = arrowIndex - 1; i >= 0; i -= 1) {
    const value = tokens[i].value;
    if (value === ")") depth += 1;
    else if (value === "(") {
      depth -= 1;
      if (depth === 0) {
        const params = [];
        for (let j = i + 1; j < arrowIndex - 1; j += 1) {
          if (isIdent(tokens[j].value) && !KEYWORDS.has(tokens[j].value)) params.push({ name: tokens[j].value, tokenIndex: j });
        }
        return params;
      }
    }
  }
  return [];
}

function collectDeclarationsAndRefs(filePath, globalScope, projectGlobals, rootDeclarations) {
  const source = fs.readFileSync(filePath, "utf8");
  const tokens = tokenize(source);
  const fileRoot = makeScope(globalScope, "root", filePath);
  globalScope.children.push(fileRoot);
  let scope = fileRoot;
  const scopeStack = [fileRoot];
  let pendingFunctionParams = null;
  let pendingFunctionParamEndIndex = -1;
  let pendingClassBody = false;
  let declarationMode = null;
  let declarationDepth = 0;
  let declarationExpectName = false;
  let skipRefs = new Set();

  function pushScope(kind, params) {
    const child = makeScope(scope, kind, filePath);
    scope.children.push(child);
    scopeStack.push(child);
    scope = child;
    for (const param of params || []) declare(scope, param);
  }

  function popScope() {
    if (scopeStack.length > 1) {
      scopeStack.pop();
      scope = scopeStack[scopeStack.length - 1];
    }
  }

  for (let i = 0; i < tokens.length; i += 1) {
    const token = tokens[i];
    const value = token.value;
    const prev = tokens[i - 1] && tokens[i - 1].value;
    const next = tokens[i + 1] && tokens[i + 1].value;

    if (value === "{") {
      if (pendingClassBody) {
        pushScope("class", []);
        pendingClassBody = false;
      } else if (pendingFunctionParams && i > pendingFunctionParamEndIndex) {
        pushScope("function", pendingFunctionParams);
        pendingFunctionParams = null;
        pendingFunctionParamEndIndex = -1;
      } else {
        pushScope("block", []);
      }
      declarationMode = null;
      continue;
    }
    if (value === "}") {
      popScope();
      declarationMode = null;
      continue;
    }

    if (value === "function") {
      const nameTok = tokens[i + 1];
      if (nameTok && isIdent(nameTok.value)) {
        declare(scope, nameTok.value);
        if (scope.kind === "root") projectGlobals.add(nameTok.value);
        skipRefs.add(i + 1);
      }
      const parenIndex = tokens.findIndex((tok, idx) => idx > i && tok.value === "(");
      if (parenIndex !== -1) {
        const parsed = parseParamNames(tokens, parenIndex);
        pendingFunctionParams = parsed.params;
        pendingFunctionParamEndIndex = parsed.end;
        for (const idx of parsed.paramIndices) skipRefs.add(idx);
      }
      continue;
    }

    if (value === "catch" && next === "(") {
      const nameTok = tokens[i + 2];
      if (nameTok && isIdent(nameTok.value)) {
        pendingFunctionParams = [nameTok.value];
        pendingFunctionParamEndIndex = i + 3;
        skipRefs.add(i + 2);
      }
      continue;
    }

    if (next === "=>") {
      skipRefs.add(i);
      continue;
    }

    if (value === "=>") {
      const params = arrowParamsBefore(tokens, i);
      const paramNames = params.map((param) => param.name);
      const paramIndexes = new Set(params.map((param) => tokens[param.tokenIndex].index));
      for (const param of params) skipRefs.add(param.tokenIndex);
      scope.refs = scope.refs.filter((ref) => !paramIndexes.has(ref.index));
      if (next === "{") {
        pendingFunctionParams = paramNames;
        pendingFunctionParamEndIndex = i;
      } else {
        for (const param of paramNames) declare(scope, param);
      }
      continue;
    }

    if ((value === "var" || value === "let" || value === "const")) {
      declarationMode = value;
      declarationDepth = 0;
      declarationExpectName = true;
      continue;
    }

    if (declarationMode) {
      if (value === "(" || value === "[" || value === "{") declarationDepth += 1;
      if (value === ")" || value === "]" || value === "}") declarationDepth -= 1;
      if ((value === ";" || value === "for") && declarationDepth <= 0) {
        declarationMode = null;
        declarationExpectName = false;
        continue;
      }
      if (value === "," && declarationDepth === 0) {
        declarationExpectName = true;
        continue;
      }
      if (value === "=" && declarationDepth === 0) {
        declarationExpectName = false;
        continue;
      }
      if (declarationExpectName && isIdent(value) && !KEYWORDS.has(value) && declarationDepth === 0 && prev !== "." && next !== ":") {
        const targetScope = declarationMode === "var" ? nearestFunctionScope(scope) : scope;
        declare(targetScope, value);
        if (targetScope.kind === "root") {
          projectGlobals.add(value);
          if (declarationMode === "let" || declarationMode === "const") {
            if (!rootDeclarations.has(value)) rootDeclarations.set(value, []);
            rootDeclarations.get(value).push({ kind: declarationMode, file: filePath, line: token.line, column: token.column });
          }
        }
        skipRefs.add(i);
        declarationExpectName = false;
        continue;
      }
      continue;
    }

    if (value === "class" && next && isIdent(next)) {
      declare(scope, next);
      if (scope.kind === "root") {
        projectGlobals.add(next);
        if (!rootDeclarations.has(next)) rootDeclarations.set(next, []);
        rootDeclarations.get(next).push({ kind: "class", file: filePath, line: token.line, column: token.column });
      }
      skipRefs.add(i + 1);
      pendingClassBody = true;
      continue;
    }

    if (scope.kind === "class" && isIdent(value) && next === "(") {
      const parsed = parseParamNames(tokens, i + 1);
      pendingFunctionParams = parsed.params;
      pendingFunctionParamEndIndex = parsed.end;
      skipRefs.add(i);
      for (const idx of parsed.paramIndices) skipRefs.add(idx);
      continue;
    }

    if (scope.kind === "class" && (value === "get" || value === "set") && tokens[i + 2] && tokens[i + 2].value === "(") {
      const parsed = parseParamNames(tokens, i + 2);
      pendingFunctionParams = parsed.params;
      pendingFunctionParamEndIndex = parsed.end;
      skipRefs.add(i);
      skipRefs.add(i + 1);
      for (const idx of parsed.paramIndices) skipRefs.add(idx);
      continue;
    }

    if ((value === "window" || value === "globalThis" || value === "root") && next === "." && tokens[i + 2] && isIdent(tokens[i + 2].value)) {
      const afterProp = tokens[i + 3] && tokens[i + 3].value;
      if (afterProp === "=") projectGlobals.add(tokens[i + 2].value);
    }

    if (!isIdent(value) || KEYWORDS.has(value) || skipRefs.has(i)) continue;
    if (prev === ".") continue;
    if (next === ":" && prev !== "?") continue;
    if (prev === ":" && tokens[i - 2] && tokens[i - 2].value === "?") continue;
    scope.refs.push(token);
  }
}

function resolveRef(scope, name, projectGlobals) {
  if (KNOWN_GLOBALS.has(name) || projectGlobals.has(name)) return true;
  let current = scope;
  while (current) {
    if (current.declarations.has(name)) return true;
    current = current.parent;
  }
  return false;
}

function collectUnresolved(scope, projectGlobals, errors) {
  for (const ref of scope.refs) {
    if (!resolveRef(scope, ref.value, projectGlobals)) {
      errors.push(`${path.relative(ROOT, scope.file)}:${ref.line}:${ref.column} '${ref.value}' is not defined`);
    }
  }
  for (const child of scope.children) collectUnresolved(child, projectGlobals, errors);
}

function jsFilesForEval(evalDir) {
  const previewNames = ["index.html", "elevator_sim.html", "elevator_simulation.html", "test.html"];
  for (const previewName of previewNames) {
    const previewPath = path.join(evalDir, previewName);
    if (!fs.existsSync(previewPath)) continue;
    const html = fs.readFileSync(previewPath, "utf8");
    const scripts = [];
    const scriptRe = /<script\b[^>]*\bsrc\s*=\s*["']([^"']+)["'][^>]*>\s*<\/script>/gi;
    let match;
    while ((match = scriptRe.exec(html))) {
      const src = match[1];
      const lower = src.toLowerCase();
      if (lower.includes("://") || lower.startsWith("data:") || lower.startsWith("about:")) continue;
      if (src.startsWith("/") || src.startsWith("\\")) continue;
      const scriptPath = path.resolve(evalDir, src);
      if (!scriptPath.startsWith(path.resolve(evalDir))) continue;
      if (fs.existsSync(scriptPath) && scriptPath.toLowerCase().endsWith(".js")) {
        scripts.push(scriptPath);
      }
    }
    if (scripts.length) return Array.from(new Set(scripts));
  }
  return fs.readdirSync(evalDir)
    .filter((name) => name.toLowerCase().endsWith(".js"))
    .filter((name) => !name.toLowerCase().endsWith("_test.js"))
    .map((name) => path.join(evalDir, name));
}

function readIfExists(filePath) {
  if (!fs.existsSync(filePath)) return "";
  return fs.readFileSync(filePath, "utf8");
}

function stripForContract(source) {
  return stripStringsAndComments(source);
}

function checkElevatorContract(evalDir) {
  const errors = [];
  if (!path.basename(evalDir).includes("elevator_prompt_wiggum")) return errors;

  const indexPath = path.join(evalDir, "index.html");
  const personPath = path.join(evalDir, "person.js");
  const elevatorPath = path.join(evalDir, "elevator.js");
  const hasElevatorFiles = [indexPath, personPath, elevatorPath].some((filePath) => fs.existsSync(filePath));
  if (!hasElevatorFiles) return errors;

  for (const filePath of [indexPath, personPath, elevatorPath]) {
    if (!fs.existsSync(filePath)) {
      errors.push(`${path.relative(ROOT, filePath)}: required elevator artifact is missing`);
    }
  }
  if (errors.length) return errors;

  const index = readIfExists(indexPath);
  const person = readIfExists(personPath);
  const elevator = readIfExists(elevatorPath);
  const allCode = `${index}\n${person}\n${elevator}`;
  const strippedPerson = stripForContract(person);
  const strippedElevator = stripForContract(elevator);

  const scriptSrcs = [];
  const scriptRe = /<script\b([^>]*)\bsrc\s*=\s*["']([^"']+)["']([^>]*)>\s*<\/script>/gi;
  let scriptMatch;
  while ((scriptMatch = scriptRe.exec(index))) {
    const attrs = `${scriptMatch[1]} ${scriptMatch[3]}`;
    scriptSrcs.push({ src: scriptMatch[2], attrs });
  }
  const expectedScripts = [
    "https://cdn.jsdelivr.net/npm/three@0.147.0/build/three.min.js",
    "https://cdn.jsdelivr.net/npm/three@0.147.0/examples/js/controls/OrbitControls.js",
    "person.js",
    "elevator.js",
  ];
  const actualScripts = scriptSrcs.map((item) => item.src);
  if (JSON.stringify(actualScripts) !== JSON.stringify(expectedScripts)) {
    errors.push(`${path.relative(ROOT, indexPath)}: script src order must exactly be Three 0.147.0, OrbitControls, person.js, elevator.js`);
  }
  for (const item of scriptSrcs) {
    if (/\btype\s*=\s*["']module["']/i.test(item.attrs)) {
      errors.push(`${path.relative(ROOT, indexPath)}: classic scripts required; remove type="module"`);
    }
  }
  const extraLocalScripts = actualScripts.filter((src) => !src.includes("://") && !["person.js", "elevator.js"].includes(src));
  if (extraLocalScripts.length) {
    errors.push(`${path.relative(ROOT, indexPath)}: unexpected local script(s): ${extraLocalScripts.join(", ")}`);
  }

  const forbiddenPatterns = [
    [/\bimport\b/m, "import"],
    [/\bexport\b/m, "export"],
    [/\btype\s*=\s*["']module["']/im, "type=\"module\""],
    [/file:\/\//i, "file://"],
    [/summary\.html/i, "summary.html"],
    [/<\s*iframe\b/i, "<iframe"],
    [/<\s*object\b/i, "<object"],
    [/<\s*embed\b/i, "<embed"],
  ];
  for (const [pattern, label] of forbiddenPatterns) {
    if (pattern.test(allCode)) errors.push(`elevator contract: forbidden ${label} found`);
  }

  const requiredConstants = new Map([
    ["FLOOR_HEIGHT", "3"],
    ["FLOOR_COUNT", "6"],
    ["BUILDING_WIDTH", "20"],
    ["BUILDING_DEPTH", "15"],
    ["SHAFT_WIDTH", "5"],
    ["SHAFT_DEPTH", "5"],
    ["ELEVATOR_SPEED", "2"],
    ["PERSON_MOVE_SPEED", "1"],
  ]);
  for (const [name, value] of requiredConstants.entries()) {
    const re = new RegExp(`(^|\\n)\\s*const\\s+${name}\\s*=\\s*${value}\\s*;`);
    if (!re.test(strippedElevator)) {
      errors.push(`${path.relative(ROOT, elevatorPath)}: missing top-level "const ${name} = ${value};"`);
    }
  }

  const requiredGlobals = [
    ["scene", /(^|\n)\s*let\s+scene\s*;/],
    ["camera", /(^|\n)\s*let\s+camera\s*;/],
    ["renderer", /(^|\n)\s*let\s+renderer\s*;/],
    ["controls", /(^|\n)\s*let\s+controls\s*;/],
    ["elevatorCar", /(^|\n)\s*let\s+elevatorCar\s*;/],
    ["people", /(^|\n)\s*let\s+people\s*=\s*\[\s*\]\s*;/],
  ];
  for (const [name, pattern] of requiredGlobals) {
    if (!pattern.test(strippedElevator)) {
      errors.push(`${path.relative(ROOT, elevatorPath)}: missing required top-level global "let ${name}"`);
    }
  }

  for (const forbidden of ["scene", "camera", "renderer", "controls", "elevatorCar", "people"]) {
    const re = new RegExp(`(^|\\n)\\s*(?:let|const|var)\\s+${forbidden}\\b`);
    if (re.test(strippedPerson)) {
      errors.push(`${path.relative(ROOT, personPath)}: must not declare ${forbidden}`);
    }
  }
  if (!/(^|\n)\s*function\s+createPerson\s*\(\s*color\s*\)/.test(strippedPerson)) {
    errors.push(`${path.relative(ROOT, personPath)}: must define global function createPerson(color)`);
  }
  for (const required of ["leftLeg", "rightLeg", "isWalking"]) {
    if (!new RegExp(`\\b${required}\\b`).test(strippedPerson)) {
      errors.push(`${path.relative(ROOT, personPath)}: createPerson userData must include ${required}`);
    }
  }
  if (!/new\s+THREE\.Group\s*\(/.test(strippedPerson) || !/return\s+[A-Za-z_$][A-Za-z0-9_$]*\s*;/.test(strippedPerson)) {
    errors.push(`${path.relative(ROOT, personPath)}: createPerson must create and return a THREE.Group`);
  }

  if (!/new\s+THREE\.Group\s*\(/.test(strippedElevator) || !/elevatorCar\s*=/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: elevatorCar must be assigned a THREE.Group`);
  }
  if (!/elevatorCar\.leftDoor\s*=\s*leftDoor\s*;/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: must store left door as elevatorCar.leftDoor = leftDoor;`);
  }
  if (!/elevatorCar\.rightDoor\s*=\s*rightDoor\s*;/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: must store right door as elevatorCar.rightDoor = rightDoor;`);
  }
  if (!/elevatorCar\.attach\s*\(/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: boarding must use elevatorCar.attach(...) to preserve world position`);
  }
  if (!/scene\.attach\s*\(/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: exiting must use scene.attach(...) to preserve world position`);
  }
  if (/elevatorCar\.add\s*\(\s*person/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: do not use elevatorCar.add(person) for boarding`);
  }
  if (!/startSimulation\s*\(/.test(strippedElevator) || !/DOMContentLoaded/.test(elevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: must auto-start startSimulation with the DOMContentLoaded pattern`);
  }

  return errors;
}

function staticCheckEval(evalDir) {
  const jsFiles = jsFilesForEval(evalDir);
  const syntaxErrors = [];
  for (const filePath of jsFiles) {
    const result = spawnSync(process.execPath, ["--check", filePath], { encoding: "utf8" });
    if (result.status !== 0) {
      const relFile = path.relative(ROOT, filePath);
      const lines = (result.stderr || result.stdout || "")
        .trim()
        .split(/\r?\n/)
        .map((line) => line.trimEnd())
        .filter((line) => line && !line.startsWith("at ") && !line.startsWith("Node.js"));
      if (lines[0] && path.resolve(lines[0].split(":").slice(0, -1).join(":")) === filePath) {
        lines[0] = lines[0].replace(filePath, relFile);
      }
      const syntaxLineIndex = lines.findIndex((line) => /^SyntaxError\b/.test(line));
      const usefulLines = syntaxLineIndex >= 0 ? lines.slice(0, syntaxLineIndex + 1) : lines.slice(0, 4);
      const message = usefulLines.join(" | ");
      syntaxErrors.push(message || `${relFile}: syntax check failed`);
    }
  }

  const globalScope = makeScope(null, "global", "");
  const projectGlobals = new Set();
  const rootDeclarations = new Map();
  for (const filePath of jsFiles) collectDeclarationsAndRefs(filePath, globalScope, projectGlobals, rootDeclarations);

  const referenceErrors = [];
  for (const child of globalScope.children) collectUnresolved(child, projectGlobals, referenceErrors);
  const duplicateErrors = [];
  for (const [name, declarations] of rootDeclarations.entries()) {
    if (declarations.length < 2) continue;
    const locations = declarations
      .map((decl) => `${path.relative(ROOT, decl.file)}:${decl.line}:${decl.column}`)
      .join(", ");
    duplicateErrors.push(`Duplicate top-level lexical declaration '${name}' in classic scripts: ${locations}`);
  }
  const contractErrors = checkElevatorContract(evalDir);
  const staticErrors = [...syntaxErrors, ...duplicateErrors, ...referenceErrors, ...contractErrors];
  return {
    checked_at: new Date().toISOString(),
    files_checked: jsFiles.map((filePath) => path.relative(ROOT, filePath)),
    static_errors: Array.from(new Set(staticErrors)).slice(0, 30),
    static_warnings: [],
  };
}

function targets(arg) {
  if (!arg || arg === "--all") {
    if (!fs.existsSync(EVALS_DIR)) return [];
    return fs.readdirSync(EVALS_DIR)
      .map((name) => path.join(EVALS_DIR, name))
      .filter((item) => fs.statSync(item).isDirectory());
  }
  const direct = path.resolve(ROOT, arg);
  return fs.existsSync(direct) && fs.statSync(direct).isDirectory() ? [direct] : [];
}

if (require.main === module) {
  const dirs = targets(process.argv[2] || "--all");
  if (!dirs.length) {
    console.error("No evaluation directories found.");
    process.exit(1);
  }
  let hadErrors = false;
  for (const dir of dirs) {
    const result = staticCheckEval(dir);
    fs.writeFileSync(path.join(dir, "static_check.json"), `${JSON.stringify(result, null, 2)}\n`, "utf8");
    if (result.static_errors.length) hadErrors = true;
    const status = result.static_errors.length ? "errors" : "ok";
    console.log(`${path.relative(ROOT, dir)}: ${status}, static check written`);
    for (const err of result.static_errors.slice(0, 5)) {
      console.log(`  - ${err}`);
    }
  }
  process.exit(hadErrors ? 2 : 0);
}

module.exports = { staticCheckEval };

#!/usr/bin/env node
const fs = require("fs");
const path = require("path");
const { spawnSync } = require("child_process");

const ROOT = process.cwd();
const EVALS_DIR = path.join(ROOT, "evals");

const KEYWORDS = new Set([
  "await", "async", "break", "case", "catch", "class", "const", "continue",
  "debugger", "default", "delete", "do", "else", "export", "extends",
  "false", "finally", "for", "from", "function", "if", "import", "in", "instanceof",
  "let", "new", "null", "of", "return", "static", "super", "switch", "this",
  "throw", "try", "typeof", "var", "void", "while", "with", "yield",
  "true",
]);

const KNOWN_GLOBALS = new Set([
  "Array", "ArrayBuffer", "BigInt", "Boolean", "DataView", "Date", "Error",
  "EvalError", "Event", "Float32Array", "Float64Array", "Infinity", "Intl",
  "JSON", "Map", "Math", "NaN", "Number", "Object", "Promise", "Proxy",
  "RangeError", "ReferenceError", "Reflect", "RegExp", "Set", "String",
  "Symbol", "SyntaxError", "THREE", "TypeError", "URIError", "URL",
  "WeakMap", "WeakSet", "alert", "cancelAnimationFrame", "clearInterval",
  "clearTimeout", "console", "decodeURIComponent", "document",
  "encodeURIComponent", "fetch", "globalThis", "isFinite", "isNaN",
  "localStorage", "module", "parseFloat", "parseInt", "performance",
  "requestAnimationFrame", "setInterval", "setTimeout", "undefined", "window",
]);

function isIdent(value) {
  return /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(value);
}

function stripStringsAndComments(source) {
  let out = "";
  for (let i = 0; i < source.length;) {
    const ch = source[i];
    const next = source[i + 1];
    if (ch === "/" && next === "/") {
      out += "  ";
      i += 2;
      while (i < source.length && source[i] !== "\n") {
        out += " ";
        i += 1;
      }
      continue;
    }
    if (ch === "/" && next === "*") {
      out += "  ";
      i += 2;
      while (i < source.length && !(source[i] === "*" && source[i + 1] === "/")) {
        out += source[i] === "\n" ? "\n" : " ";
        i += 1;
      }
      if (i < source.length) {
        out += "  ";
        i += 2;
      }
      continue;
    }
    if (ch === "\"" || ch === "'" || ch === "`") {
      const quote = ch;
      out += " ";
      i += 1;
      while (i < source.length) {
        if (source[i] === "\\") {
          out += " ";
          i += 1;
          if (i < source.length) {
            out += source[i] === "\n" ? "\n" : " ";
            i += 1;
          }
          continue;
        }
        if (source[i] === quote) {
          out += " ";
          i += 1;
          break;
        }
        out += source[i] === "\n" ? "\n" : " ";
        i += 1;
      }
      continue;
    }
    out += ch;
    i += 1;
  }
  return out;
}

function tokenize(source) {
  const stripped = stripStringsAndComments(source);
  const tokens = [];
  const re = /0x[0-9A-Fa-f]+|\d+(?:\.\d+)?|[A-Za-z_$][A-Za-z0-9_$]*|=>|===|!==|==|!=|<=|>=|\+\+|--|&&|\|\||[{}()[\].,;:=+\-*/%<>!?]/g;
  const lineStarts = [0];
  for (let i = 0; i < stripped.length; i += 1) {
    if (stripped[i] === "\n") lineStarts.push(i + 1);
  }
  function position(index) {
    let lo = 0;
    let hi = lineStarts.length - 1;
    while (lo <= hi) {
      const mid = Math.floor((lo + hi) / 2);
      if (lineStarts[mid] <= index) lo = mid + 1;
      else hi = mid - 1;
    }
    const lineIndex = Math.max(0, hi);
    return { line: lineIndex + 1, column: index - lineStarts[lineIndex] + 1 };
  }
  let match;
  while ((match = re.exec(stripped))) {
    tokens.push({ value: match[0], index: match.index, ...position(match.index) });
  }
  return tokens;
}

function makeScope(parent, kind, file) {
  return { parent, kind, file, declarations: new Set(), refs: [], children: [] };
}

function declare(scope, name) {
  if (name && isIdent(name) && !KEYWORDS.has(name)) scope.declarations.add(name);
}

function nearestFunctionScope(scope) {
  let current = scope;
  while (current && current.kind !== "function" && current.kind !== "root") {
    current = current.parent;
  }
  return current || scope;
}

function parseParamNames(tokens, startIndex) {
  const params = [];
  const paramIndices = [];
  let depth = 0;
  for (let i = startIndex; i < tokens.length; i += 1) {
    const value = tokens[i].value;
    if (value === "(") {
      depth += 1;
      continue;
    }
    if (value === ")") {
      depth -= 1;
      if (depth === 0) return { params, paramIndices, end: i };
      continue;
    }
    if (depth === 1 && isIdent(value) && !KEYWORDS.has(value)) {
      params.push(value);
      paramIndices.push(i);
    }
  }
  return { params, paramIndices, end: startIndex };
}

function arrowParamsBefore(tokens, arrowIndex) {
  const prev = tokens[arrowIndex - 1];
  if (!prev) return [];
  if (isIdent(prev.value) && !KEYWORDS.has(prev.value)) return [{ name: prev.value, tokenIndex: arrowIndex - 1 }];
  if (prev.value !== ")") return [];
  let depth = 0;
  for (let i = arrowIndex - 1; i >= 0; i -= 1) {
    const value = tokens[i].value;
    if (value === ")") depth += 1;
    else if (value === "(") {
      depth -= 1;
      if (depth === 0) {
        const params = [];
        for (let j = i + 1; j < arrowIndex - 1; j += 1) {
          if (isIdent(tokens[j].value) && !KEYWORDS.has(tokens[j].value)) params.push({ name: tokens[j].value, tokenIndex: j });
        }
        return params;
      }
    }
  }
  return [];
}

function collectDeclarationsAndRefs(filePath, globalScope, projectGlobals, rootDeclarations) {
  const source = fs.readFileSync(filePath, "utf8");
  const tokens = tokenize(source);
  const fileRoot = makeScope(globalScope, "root", filePath);
  globalScope.children.push(fileRoot);
  let scope = fileRoot;
  const scopeStack = [fileRoot];
  let pendingFunctionParams = null;
  let pendingFunctionParamEndIndex = -1;
  let pendingClassBody = false;
  let declarationMode = null;
  let declarationDepth = 0;
  let declarationExpectName = false;
  let skipRefs = new Set();

  function pushScope(kind, params) {
    const child = makeScope(scope, kind, filePath);
    scope.children.push(child);
    scopeStack.push(child);
    scope = child;
    for (const param of params || []) declare(scope, param);
  }

  function popScope() {
    if (scopeStack.length > 1) {
      scopeStack.pop();
      scope = scopeStack[scopeStack.length - 1];
    }
  }

  for (let i = 0; i < tokens.length; i += 1) {
    const token = tokens[i];
    const value = token.value;
    const prev = tokens[i - 1] && tokens[i - 1].value;
    const next = tokens[i + 1] && tokens[i + 1].value;

    if (value === "{") {
      if (pendingClassBody) {
        pushScope("class", []);
        pendingClassBody = false;
      } else if (pendingFunctionParams && i > pendingFunctionParamEndIndex) {
        pushScope("function", pendingFunctionParams);
        pendingFunctionParams = null;
        pendingFunctionParamEndIndex = -1;
      } else {
        pushScope("block", []);
      }
      declarationMode = null;
      continue;
    }
    if (value === "}") {
      popScope();
      declarationMode = null;
      continue;
    }

    if (value === "function") {
      const nameTok = tokens[i + 1];
      if (nameTok && isIdent(nameTok.value)) {
        declare(scope, nameTok.value);
        if (scope.kind === "root") projectGlobals.add(nameTok.value);
        skipRefs.add(i + 1);
      }
      const parenIndex = tokens.findIndex((tok, idx) => idx > i && tok.value === "(");
      if (parenIndex !== -1) {
        const parsed = parseParamNames(tokens, parenIndex);
        pendingFunctionParams = parsed.params;
        pendingFunctionParamEndIndex = parsed.end;
        for (const idx of parsed.paramIndices) skipRefs.add(idx);
      }
      continue;
    }

    if (value === "catch" && next === "(") {
      const nameTok = tokens[i + 2];
      if (nameTok && isIdent(nameTok.value)) {
        pendingFunctionParams = [nameTok.value];
        pendingFunctionParamEndIndex = i + 3;
        skipRefs.add(i + 2);
      }
      continue;
    }

    if (next === "=>") {
      skipRefs.add(i);
      continue;
    }

    if (value === "=>") {
      const params = arrowParamsBefore(tokens, i);
      const paramNames = params.map((param) => param.name);
      const paramIndexes = new Set(params.map((param) => tokens[param.tokenIndex].index));
      for (const param of params) skipRefs.add(param.tokenIndex);
      scope.refs = scope.refs.filter((ref) => !paramIndexes.has(ref.index));
      if (next === "{") {
        pendingFunctionParams = paramNames;
        pendingFunctionParamEndIndex = i;
      } else {
        for (const param of paramNames) declare(scope, param);
      }
      continue;
    }

    if ((value === "var" || value === "let" || value === "const")) {
      declarationMode = value;
      declarationDepth = 0;
      declarationExpectName = true;
      continue;
    }

    if (declarationMode) {
      if (value === "(" || value === "[" || value === "{") declarationDepth += 1;
      if (value === ")" || value === "]" || value === "}") declarationDepth -= 1;
      if ((value === ";" || value === "for") && declarationDepth <= 0) {
        declarationMode = null;
        declarationExpectName = false;
        continue;
      }
      if (value === "," && declarationDepth === 0) {
        declarationExpectName = true;
        continue;
      }
      if (value === "=" && declarationDepth === 0) {
        declarationExpectName = false;
        continue;
      }
      if (declarationExpectName && isIdent(value) && !KEYWORDS.has(value) && declarationDepth === 0 && prev !== "." && next !== ":") {
        const targetScope = declarationMode === "var" ? nearestFunctionScope(scope) : scope;
        declare(targetScope, value);
        if (targetScope.kind === "root") {
          projectGlobals.add(value);
          if (declarationMode === "let" || declarationMode === "const") {
            if (!rootDeclarations.has(value)) rootDeclarations.set(value, []);
            rootDeclarations.get(value).push({ kind: declarationMode, file: filePath, line: token.line, column: token.column });
          }
        }
        skipRefs.add(i);
        declarationExpectName = false;
        continue;
      }
      continue;
    }

    if (value === "class" && next && isIdent(next)) {
      declare(scope, next);
      if (scope.kind === "root") {
        projectGlobals.add(next);
        if (!rootDeclarations.has(next)) rootDeclarations.set(next, []);
        rootDeclarations.get(next).push({ kind: "class", file: filePath, line: token.line, column: token.column });
      }
      skipRefs.add(i + 1);
      pendingClassBody = true;
      continue;
    }

    if (scope.kind === "class" && isIdent(value) && next === "(") {
      const parsed = parseParamNames(tokens, i + 1);
      pendingFunctionParams = parsed.params;
      pendingFunctionParamEndIndex = parsed.end;
      skipRefs.add(i);
      for (const idx of parsed.paramIndices) skipRefs.add(idx);
      continue;
    }

    if (scope.kind === "class" && (value === "get" || value === "set") && tokens[i + 2] && tokens[i + 2].value === "(") {
      const parsed = parseParamNames(tokens, i + 2);
      pendingFunctionParams = parsed.params;
      pendingFunctionParamEndIndex = parsed.end;
      skipRefs.add(i);
      skipRefs.add(i + 1);
      for (const idx of parsed.paramIndices) skipRefs.add(idx);
      continue;
    }

    if ((value === "window" || value === "globalThis" || value === "root") && next === "." && tokens[i + 2] && isIdent(tokens[i + 2].value)) {
      const afterProp = tokens[i + 3] && tokens[i + 3].value;
      if (afterProp === "=") projectGlobals.add(tokens[i + 2].value);
    }

    if (!isIdent(value) || KEYWORDS.has(value) || skipRefs.has(i)) continue;
    if (prev === ".") continue;
    if (next === ":" && prev !== "?") continue;
    if (prev === ":" && tokens[i - 2] && tokens[i - 2].value === "?") continue;
    scope.refs.push(token);
  }
}

function resolveRef(scope, name, projectGlobals) {
  if (KNOWN_GLOBALS.has(name) || projectGlobals.has(name)) return true;
  let current = scope;
  while (current) {
    if (current.declarations.has(name)) return true;
    current = current.parent;
  }
  return false;
}

function collectUnresolved(scope, projectGlobals, errors) {
  for (const ref of scope.refs) {
    if (!resolveRef(scope, ref.value, projectGlobals)) {
      errors.push(`${path.relative(ROOT, scope.file)}:${ref.line}:${ref.column} '${ref.value}' is not defined`);
    }
  }
  for (const child of scope.children) collectUnresolved(child, projectGlobals, errors);
}

function jsFilesForEval(evalDir) {
  const previewNames = ["index.html", "elevator_sim.html", "elevator_simulation.html", "test.html"];
  for (const previewName of previewNames) {
    const previewPath = path.join(evalDir, previewName);
    if (!fs.existsSync(previewPath)) continue;
    const html = fs.readFileSync(previewPath, "utf8");
    const scripts = [];
    const scriptRe = /<script\b[^>]*\bsrc\s*=\s*["']([^"']+)["'][^>]*>\s*<\/script>/gi;
    let match;
    while ((match = scriptRe.exec(html))) {
      const src = match[1];
      const lower = src.toLowerCase();
      if (lower.includes("://") || lower.startsWith("data:") || lower.startsWith("about:")) continue;
      if (src.startsWith("/") || src.startsWith("\\")) continue;
      const scriptPath = path.resolve(evalDir, src);
      if (!scriptPath.startsWith(path.resolve(evalDir))) continue;
      if (fs.existsSync(scriptPath) && scriptPath.toLowerCase().endsWith(".js")) {
        scripts.push(scriptPath);
      }
    }
    if (scripts.length) return Array.from(new Set(scripts));
  }
  return fs.readdirSync(evalDir)
    .filter((name) => name.toLowerCase().endsWith(".js"))
    .filter((name) => !name.toLowerCase().endsWith("_test.js"))
    .map((name) => path.join(evalDir, name));
}

function readIfExists(filePath) {
  if (!fs.existsSync(filePath)) return "";
  return fs.readFileSync(filePath, "utf8");
}

function stripForContract(source) {
  return stripStringsAndComments(source);
}

function checkElevatorContract(evalDir) {
  const errors = [];
  if (!path.basename(evalDir).includes("elevator_prompt_wiggum")) return errors;

  const indexPath = path.join(evalDir, "index.html");
  const personPath = path.join(evalDir, "person.js");
  const elevatorPath = path.join(evalDir, "elevator.js");
  const hasElevatorFiles = [indexPath, personPath, elevatorPath].some((filePath) => fs.existsSync(filePath));
  if (!hasElevatorFiles) return errors;

  for (const filePath of [indexPath, personPath, elevatorPath]) {
    if (!fs.existsSync(filePath)) {
      errors.push(`${path.relative(ROOT, filePath)}: required elevator artifact is missing`);
    }
  }
  if (errors.length) return errors;

  const index = readIfExists(indexPath);
  const person = readIfExists(personPath);
  const elevator = readIfExists(elevatorPath);
  const allCode = `${index}\n${person}\n${elevator}`;
  const strippedPerson = stripForContract(person);
  const strippedElevator = stripForContract(elevator);

  const scriptSrcs = [];
  const scriptRe = /<script\b([^>]*)\bsrc\s*=\s*["']([^"']+)["']([^>]*)>\s*<\/script>/gi;
  let scriptMatch;
  while ((scriptMatch = scriptRe.exec(index))) {
    const attrs = `${scriptMatch[1]} ${scriptMatch[3]}`;
    scriptSrcs.push({ src: scriptMatch[2], attrs });
  }
  const expectedScripts = [
    "https://cdn.jsdelivr.net/npm/three@0.147.0/build/three.min.js",
    "https://cdn.jsdelivr.net/npm/three@0.147.0/examples/js/controls/OrbitControls.js",
    "person.js",
    "elevator.js",
  ];
  const actualScripts = scriptSrcs.map((item) => item.src);
  if (JSON.stringify(actualScripts) !== JSON.stringify(expectedScripts)) {
    errors.push(`${path.relative(ROOT, indexPath)}: script src order must exactly be Three 0.147.0, OrbitControls, person.js, elevator.js`);
  }
  for (const item of scriptSrcs) {
    if (/\btype\s*=\s*["']module["']/i.test(item.attrs)) {
      errors.push(`${path.relative(ROOT, indexPath)}: classic scripts required; remove type="module"`);
    }
  }
  const extraLocalScripts = actualScripts.filter((src) => !src.includes("://") && !["person.js", "elevator.js"].includes(src));
  if (extraLocalScripts.length) {
    errors.push(`${path.relative(ROOT, indexPath)}: unexpected local script(s): ${extraLocalScripts.join(", ")}`);
  }

  const forbiddenPatterns = [
    [/\bimport\b/m, "import"],
    [/\bexport\b/m, "export"],
    [/\btype\s*=\s*["']module["']/im, "type=\"module\""],
    [/file:\/\//i, "file://"],
    [/summary\.html/i, "summary.html"],
    [/<\s*iframe\b/i, "<iframe"],
    [/<\s*object\b/i, "<object"],
    [/<\s*embed\b/i, "<embed"],
  ];
  for (const [pattern, label] of forbiddenPatterns) {
    if (pattern.test(allCode)) errors.push(`elevator contract: forbidden ${label} found`);
  }

  const requiredConstants = new Map([
    ["FLOOR_HEIGHT", "3"],
    ["FLOOR_COUNT", "6"],
    ["BUILDING_WIDTH", "20"],
    ["BUILDING_DEPTH", "15"],
    ["SHAFT_WIDTH", "5"],
    ["SHAFT_DEPTH", "5"],
    ["ELEVATOR_SPEED", "2"],
    ["PERSON_MOVE_SPEED", "1"],
  ]);
  for (const [name, value] of requiredConstants.entries()) {
    const re = new RegExp(`(^|\\n)\\s*const\\s+${name}\\s*=\\s*${value}\\s*;`);
    if (!re.test(strippedElevator)) {
      errors.push(`${path.relative(ROOT, elevatorPath)}: missing top-level "const ${name} = ${value};"`);
    }
  }

  const requiredGlobals = [
    ["scene", /(^|\n)\s*let\s+scene\s*;/],
    ["camera", /(^|\n)\s*let\s+camera\s*;/],
    ["renderer", /(^|\n)\s*let\s+renderer\s*;/],
    ["controls", /(^|\n)\s*let\s+controls\s*;/],
    ["elevatorCar", /(^|\n)\s*let\s+elevatorCar\s*;/],
    ["people", /(^|\n)\s*let\s+people\s*=\s*\[\s*\]\s*;/],
  ];
  for (const [name, pattern] of requiredGlobals) {
    if (!pattern.test(strippedElevator)) {
      errors.push(`${path.relative(ROOT, elevatorPath)}: missing required top-level global "let ${name}"`);
    }
  }

  for (const forbidden of ["scene", "camera", "renderer", "controls", "elevatorCar", "people"]) {
    const re = new RegExp(`(^|\\n)\\s*(?:let|const|var)\\s+${forbidden}\\b`);
    if (re.test(strippedPerson)) {
      errors.push(`${path.relative(ROOT, personPath)}: must not declare ${forbidden}`);
    }
  }
  if (!/(^|\n)\s*function\s+createPerson\s*\(\s*color\s*\)/.test(strippedPerson)) {
    errors.push(`${path.relative(ROOT, personPath)}: must define global function createPerson(color)`);
  }
  for (const required of ["leftLeg", "rightLeg", "isWalking"]) {
    if (!new RegExp(`\\b${required}\\b`).test(strippedPerson)) {
      errors.push(`${path.relative(ROOT, personPath)}: createPerson userData must include ${required}`);
    }
  }
  if (!/new\s+THREE\.Group\s*\(/.test(strippedPerson) || !/return\s+[A-Za-z_$][A-Za-z0-9_$]*\s*;/.test(strippedPerson)) {
    errors.push(`${path.relative(ROOT, personPath)}: createPerson must create and return a THREE.Group`);
  }

  if (!/new\s+THREE\.Group\s*\(/.test(strippedElevator) || !/elevatorCar\s*=/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: elevatorCar must be assigned a THREE.Group`);
  }
  if (!/elevatorCar\.leftDoor\s*=\s*leftDoor\s*;/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: must store left door as elevatorCar.leftDoor = leftDoor;`);
  }
  if (!/elevatorCar\.rightDoor\s*=\s*rightDoor\s*;/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: must store right door as elevatorCar.rightDoor = rightDoor;`);
  }
  if (!/elevatorCar\.attach\s*\(/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: boarding must use elevatorCar.attach(...) to preserve world position`);
  }
  if (!/scene\.attach\s*\(/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: exiting must use scene.attach(...) to preserve world position`);
  }
  if (/elevatorCar\.add\s*\(\s*person/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: do not use elevatorCar.add(person) for boarding`);
  }
  if (!/startSimulation\s*\(/.test(strippedElevator) || !/DOMContentLoaded/.test(elevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: must auto-start startSimulation with the DOMContentLoaded pattern`);
  }

  return errors;
}

function staticCheckEval(evalDir) {
  const jsFiles = jsFilesForEval(evalDir);
  const syntaxErrors = [];
  for (const filePath of jsFiles) {
    const result = spawnSync(process.execPath, ["--check", filePath], { encoding: "utf8" });
    if (result.status !== 0) {
      const relFile = path.relative(ROOT, filePath);
      const lines = (result.stderr || result.stdout || "")
        .trim()
        .split(/\r?\n/)
        .map((line) => line.trimEnd())
        .filter((line) => line && !line.startsWith("at ") && !line.startsWith("Node.js"));
      if (lines[0] && path.resolve(lines[0].split(":").slice(0, -1).join(":")) === filePath) {
        lines[0] = lines[0].replace(filePath, relFile);
      }
      const syntaxLineIndex = lines.findIndex((line) => /^SyntaxError\b/.test(line));
      const usefulLines = syntaxLineIndex >= 0 ? lines.slice(0, syntaxLineIndex + 1) : lines.slice(0, 4);
      const message = usefulLines.join(" | ");
      syntaxErrors.push(message || `${relFile}: syntax check failed`);
    }
  }

  const globalScope = makeScope(null, "global", "");
  const projectGlobals = new Set();
  const rootDeclarations = new Map();
  for (const filePath of jsFiles) collectDeclarationsAndRefs(filePath, globalScope, projectGlobals, rootDeclarations);

  const referenceErrors = [];
  for (const child of globalScope.children) collectUnresolved(child, projectGlobals, referenceErrors);
  const duplicateErrors = [];
  for (const [name, declarations] of rootDeclarations.entries()) {
    if (declarations.length < 2) continue;
    const locations = declarations
      .map((decl) => `${path.relative(ROOT, decl.file)}:${decl.line}:${decl.column}`)
      .join(", ");
    duplicateErrors.push(`Duplicate top-level lexical declaration '${name}' in classic scripts: ${locations}`);
  }
  const contractErrors = checkElevatorContract(evalDir);
  const staticErrors = [...syntaxErrors, ...duplicateErrors, ...referenceErrors, ...contractErrors];
  return {
    checked_at: new Date().toISOString(),
    files_checked: jsFiles.map((filePath) => path.relative(ROOT, filePath)),
    static_errors: Array.from(new Set(staticErrors)).slice(0, 30),
    static_warnings: [],
  };
}

function targets(arg) {
  if (!arg || arg === "--all") {
    if (!fs.existsSync(EVALS_DIR)) return [];
    return fs.readdirSync(EVALS_DIR)
      .map((name) => path.join(EVALS_DIR, name))
      .filter((item) => fs.statSync(item).isDirectory());
  }
  const direct = path.resolve(ROOT, arg);
  return fs.existsSync(direct) && fs.statSync(direct).isDirectory() ? [direct] : [];
}

if (require.main === module) {
  const dirs = targets(process.argv[2] || "--all");
  if (!dirs.length) {
    console.error("No evaluation directories found.");
    process.exit(1);
  }
  let hadErrors = false;
  for (const dir of dirs) {
    const result = staticCheckEval(dir);
    fs.writeFileSync(path.join(dir, "static_check.json"), `${JSON.stringify(result, null, 2)}\n`, "utf8");
    if (result.static_errors.length) hadErrors = true;
    const status = result.static_errors.length ? "errors" : "ok";
    console.log(`${path.relative(ROOT, dir)}: ${status}, static check written`);
    for (const err of result.static_errors.slice(0, 5)) {
      console.log(`  - ${err}`);
    }
  }
  process.exit(hadErrors ? 2 : 0);
}

module.exports = { staticCheckEval };

#!/usr/bin/env node
const fs = require("fs");
const path = require("path");
const { spawnSync } = require("child_process");

const ROOT = process.cwd();
const EVALS_DIR = path.join(ROOT, "evals");

const KEYWORDS = new Set([
  "await", "async", "break", "case", "catch", "class", "const", "continue",
  "debugger", "default", "delete", "do", "else", "export", "extends",
  "false", "finally", "for", "from", "function", "if", "import", "in", "instanceof",
  "let", "new", "null", "of", "return", "static", "super", "switch", "this",
  "throw", "try", "typeof", "var", "void", "while", "with", "yield",
  "true",
]);

const KNOWN_GLOBALS = new Set([
  "Array", "ArrayBuffer", "BigInt", "Boolean", "DataView", "Date", "Error",
  "EvalError", "Event", "Float32Array", "Float64Array", "Infinity", "Intl",
  "JSON", "Map", "Math", "NaN", "Number", "Object", "Promise", "Proxy",
  "RangeError", "ReferenceError", "Reflect", "RegExp", "Set", "String",
  "Symbol", "SyntaxError", "THREE", "TypeError", "URIError", "URL",
  "WeakMap", "WeakSet", "alert", "cancelAnimationFrame", "clearInterval",
  "clearTimeout", "console", "decodeURIComponent", "document",
  "encodeURIComponent", "fetch", "globalThis", "isFinite", "isNaN",
  "localStorage", "module", "parseFloat", "parseInt", "performance",
  "requestAnimationFrame", "setInterval", "setTimeout", "undefined", "window",
]);

function isIdent(value) {
  return /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(value);
}

function stripStringsAndComments(source) {
  let out = "";
  for (let i = 0; i < source.length;) {
    const ch = source[i];
    const next = source[i + 1];
    if (ch === "/" && next === "/") {
      out += "  ";
      i += 2;
      while (i < source.length && source[i] !== "\n") {
        out += " ";
        i += 1;
      }
      continue;
    }
    if (ch === "/" && next === "*") {
      out += "  ";
      i += 2;
      while (i < source.length && !(source[i] === "*" && source[i + 1] === "/")) {
        out += source[i] === "\n" ? "\n" : " ";
        i += 1;
      }
      if (i < source.length) {
        out += "  ";
        i += 2;
      }
      continue;
    }
    if (ch === "\"" || ch === "'" || ch === "`") {
      const quote = ch;
      out += " ";
      i += 1;
      while (i < source.length) {
        if (source[i] === "\\") {
          out += " ";
          i += 1;
          if (i < source.length) {
            out += source[i] === "\n" ? "\n" : " ";
            i += 1;
          }
          continue;
        }
        if (source[i] === quote) {
          out += " ";
          i += 1;
          break;
        }
        out += source[i] === "\n" ? "\n" : " ";
        i += 1;
      }
      continue;
    }
    out += ch;
    i += 1;
  }
  return out;
}

function tokenize(source) {
  const stripped = stripStringsAndComments(source);
  const tokens = [];
  const re = /0x[0-9A-Fa-f]+|\d+(?:\.\d+)?|[A-Za-z_$][A-Za-z0-9_$]*|=>|===|!==|==|!=|<=|>=|\+\+|--|&&|\|\||[{}()[\].,;:=+\-*/%<>!?]/g;
  const lineStarts = [0];
  for (let i = 0; i < stripped.length; i += 1) {
    if (stripped[i] === "\n") lineStarts.push(i + 1);
  }
  function position(index) {
    let lo = 0;
    let hi = lineStarts.length - 1;
    while (lo <= hi) {
      const mid = Math.floor((lo + hi) / 2);
      if (lineStarts[mid] <= index) lo = mid + 1;
      else hi = mid - 1;
    }
    const lineIndex = Math.max(0, hi);
    return { line: lineIndex + 1, column: index - lineStarts[lineIndex] + 1 };
  }
  let match;
  while ((match = re.exec(stripped))) {
    tokens.push({ value: match[0], index: match.index, ...position(match.index) });
  }
  return tokens;
}

function makeScope(parent, kind, file) {
  return { parent, kind, file, declarations: new Set(), refs: [], children: [] };
}

function declare(scope, name) {
  if (name && isIdent(name) && !KEYWORDS.has(name)) scope.declarations.add(name);
}

function nearestFunctionScope(scope) {
  let current = scope;
  while (current && current.kind !== "function" && current.kind !== "root") {
    current = current.parent;
  }
  return current || scope;
}

function parseParamNames(tokens, startIndex) {
  const params = [];
  const paramIndices = [];
  let depth = 0;
  for (let i = startIndex; i < tokens.length; i += 1) {
    const value = tokens[i].value;
    if (value === "(") {
      depth += 1;
      continue;
    }
    if (value === ")") {
      depth -= 1;
      if (depth === 0) return { params, paramIndices, end: i };
      continue;
    }
    if (depth === 1 && isIdent(value) && !KEYWORDS.has(value)) {
      params.push(value);
      paramIndices.push(i);
    }
  }
  return { params, paramIndices, end: startIndex };
}

function arrowParamsBefore(tokens, arrowIndex) {
  const prev = tokens[arrowIndex - 1];
  if (!prev) return [];
  if (isIdent(prev.value) && !KEYWORDS.has(prev.value)) return [{ name: prev.value, tokenIndex: arrowIndex - 1 }];
  if (prev.value !== ")") return [];
  let depth = 0;
  for (let i = arrowIndex - 1; i >= 0; i -= 1) {
    const value = tokens[i].value;
    if (value === ")") depth += 1;
    else if (value === "(") {
      depth -= 1;
      if (depth === 0) {
        const params = [];
        for (let j = i + 1; j < arrowIndex - 1; j += 1) {
          if (isIdent(tokens[j].value) && !KEYWORDS.has(tokens[j].value)) params.push({ name: tokens[j].value, tokenIndex: j });
        }
        return params;
      }
    }
  }
  return [];
}

function collectDeclarationsAndRefs(filePath, globalScope, projectGlobals, rootDeclarations) {
  const source = fs.readFileSync(filePath, "utf8");
  const tokens = tokenize(source);
  const fileRoot = makeScope(globalScope, "root", filePath);
  globalScope.children.push(fileRoot);
  let scope = fileRoot;
  const scopeStack = [fileRoot];
  let pendingFunctionParams = null;
  let pendingFunctionParamEndIndex = -1;
  let pendingClassBody = false;
  let declarationMode = null;
  let declarationDepth = 0;
  let declarationExpectName = false;
  let skipRefs = new Set();

  function pushScope(kind, params) {
    const child = makeScope(scope, kind, filePath);
    scope.children.push(child);
    scopeStack.push(child);
    scope = child;
    for (const param of params || []) declare(scope, param);
  }

  function popScope() {
    if (scopeStack.length > 1) {
      scopeStack.pop();
      scope = scopeStack[scopeStack.length - 1];
    }
  }

  for (let i = 0; i < tokens.length; i += 1) {
    const token = tokens[i];
    const value = token.value;
    const prev = tokens[i - 1] && tokens[i - 1].value;
    const next = tokens[i + 1] && tokens[i + 1].value;

    if (value === "{") {
      if (pendingClassBody) {
        pushScope("class", []);
        pendingClassBody = false;
      } else if (pendingFunctionParams && i > pendingFunctionParamEndIndex) {
        pushScope("function", pendingFunctionParams);
        pendingFunctionParams = null;
        pendingFunctionParamEndIndex = -1;
      } else {
        pushScope("block", []);
      }
      declarationMode = null;
      continue;
    }
    if (value === "}") {
      popScope();
      declarationMode = null;
      continue;
    }

    if (value === "function") {
      const nameTok = tokens[i + 1];
      if (nameTok && isIdent(nameTok.value)) {
        declare(scope, nameTok.value);
        if (scope.kind === "root") projectGlobals.add(nameTok.value);
        skipRefs.add(i + 1);
      }
      const parenIndex = tokens.findIndex((tok, idx) => idx > i && tok.value === "(");
      if (parenIndex !== -1) {
        const parsed = parseParamNames(tokens, parenIndex);
        pendingFunctionParams = parsed.params;
        pendingFunctionParamEndIndex = parsed.end;
        for (const idx of parsed.paramIndices) skipRefs.add(idx);
      }
      continue;
    }

    if (value === "catch" && next === "(") {
      const nameTok = tokens[i + 2];
      if (nameTok && isIdent(nameTok.value)) {
        pendingFunctionParams = [nameTok.value];
        pendingFunctionParamEndIndex = i + 3;
        skipRefs.add(i + 2);
      }
      continue;
    }

    if (next === "=>") {
      skipRefs.add(i);
      continue;
    }

    if (value === "=>") {
      const params = arrowParamsBefore(tokens, i);
      const paramNames = params.map((param) => param.name);
      const paramIndexes = new Set(params.map((param) => tokens[param.tokenIndex].index));
      for (const param of params) skipRefs.add(param.tokenIndex);
      scope.refs = scope.refs.filter((ref) => !paramIndexes.has(ref.index));
      if (next === "{") {
        pendingFunctionParams = paramNames;
        pendingFunctionParamEndIndex = i;
      } else {
        for (const param of paramNames) declare(scope, param);
      }
      continue;
    }

    if ((value === "var" || value === "let" || value === "const")) {
      declarationMode = value;
      declarationDepth = 0;
      declarationExpectName = true;
      continue;
    }

    if (declarationMode) {
      if (value === "(" || value === "[" || value === "{") declarationDepth += 1;
      if (value === ")" || value === "]" || value === "}") declarationDepth -= 1;
      if ((value === ";" || value === "for") && declarationDepth <= 0) {
        declarationMode = null;
        declarationExpectName = false;
        continue;
      }
      if (value === "," && declarationDepth === 0) {
        declarationExpectName = true;
        continue;
      }
      if (value === "=" && declarationDepth === 0) {
        declarationExpectName = false;
        continue;
      }
      if (declarationExpectName && isIdent(value) && !KEYWORDS.has(value) && declarationDepth === 0 && prev !== "." && next !== ":") {
        const targetScope = declarationMode === "var" ? nearestFunctionScope(scope) : scope;
        declare(targetScope, value);
        if (targetScope.kind === "root") {
          projectGlobals.add(value);
          if (declarationMode === "let" || declarationMode === "const") {
            if (!rootDeclarations.has(value)) rootDeclarations.set(value, []);
            rootDeclarations.get(value).push({ kind: declarationMode, file: filePath, line: token.line, column: token.column });
          }
        }
        skipRefs.add(i);
        declarationExpectName = false;
        continue;
      }
      continue;
    }

    if (value === "class" && next && isIdent(next)) {
      declare(scope, next);
      if (scope.kind === "root") {
        projectGlobals.add(next);
        if (!rootDeclarations.has(next)) rootDeclarations.set(next, []);
        rootDeclarations.get(next).push({ kind: "class", file: filePath, line: token.line, column: token.column });
      }
      skipRefs.add(i + 1);
      pendingClassBody = true;
      continue;
    }

    if (scope.kind === "class" && isIdent(value) && next === "(") {
      const parsed = parseParamNames(tokens, i + 1);
      pendingFunctionParams = parsed.params;
      pendingFunctionParamEndIndex = parsed.end;
      skipRefs.add(i);
      for (const idx of parsed.paramIndices) skipRefs.add(idx);
      continue;
    }

    if (scope.kind === "class" && (value === "get" || value === "set") && tokens[i + 2] && tokens[i + 2].value === "(") {
      const parsed = parseParamNames(tokens, i + 2);
      pendingFunctionParams = parsed.params;
      pendingFunctionParamEndIndex = parsed.end;
      skipRefs.add(i);
      skipRefs.add(i + 1);
      for (const idx of parsed.paramIndices) skipRefs.add(idx);
      continue;
    }

    if ((value === "window" || value === "globalThis" || value === "root") && next === "." && tokens[i + 2] && isIdent(tokens[i + 2].value)) {
      const afterProp = tokens[i + 3] && tokens[i + 3].value;
      if (afterProp === "=") projectGlobals.add(tokens[i + 2].value);
    }

    if (!isIdent(value) || KEYWORDS.has(value) || skipRefs.has(i)) continue;
    if (prev === ".") continue;
    if (next === ":" && prev !== "?") continue;
    if (prev === ":" && tokens[i - 2] && tokens[i - 2].value === "?") continue;
    scope.refs.push(token);
  }
}

function resolveRef(scope, name, projectGlobals) {
  if (KNOWN_GLOBALS.has(name) || projectGlobals.has(name)) return true;
  let current = scope;
  while (current) {
    if (current.declarations.has(name)) return true;
    current = current.parent;
  }
  return false;
}

function collectUnresolved(scope, projectGlobals, errors) {
  for (const ref of scope.refs) {
    if (!resolveRef(scope, ref.value, projectGlobals)) {
      errors.push(`${path.relative(ROOT, scope.file)}:${ref.line}:${ref.column} '${ref.value}' is not defined`);
    }
  }
  for (const child of scope.children) collectUnresolved(child, projectGlobals, errors);
}

function jsFilesForEval(evalDir) {
  const previewNames = ["index.html", "elevator_sim.html", "elevator_simulation.html", "test.html"];
  for (const previewName of previewNames) {
    const previewPath = path.join(evalDir, previewName);
    if (!fs.existsSync(previewPath)) continue;
    const html = fs.readFileSync(previewPath, "utf8");
    const scripts = [];
    const scriptRe = /<script\b[^>]*\bsrc\s*=\s*["']([^"']+)["'][^>]*>\s*<\/script>/gi;
    let match;
    while ((match = scriptRe.exec(html))) {
      const src = match[1];
      const lower = src.toLowerCase();
      if (lower.includes("://") || lower.startsWith("data:") || lower.startsWith("about:")) continue;
      if (src.startsWith("/") || src.startsWith("\\")) continue;
      const scriptPath = path.resolve(evalDir, src);
      if (!scriptPath.startsWith(path.resolve(evalDir))) continue;
      if (fs.existsSync(scriptPath) && scriptPath.toLowerCase().endsWith(".js")) {
        scripts.push(scriptPath);
      }
    }
    if (scripts.length) return Array.from(new Set(scripts));
  }
  return fs.readdirSync(evalDir)
    .filter((name) => name.toLowerCase().endsWith(".js"))
    .filter((name) => !name.toLowerCase().endsWith("_test.js"))
    .map((name) => path.join(evalDir, name));
}

function readIfExists(filePath) {
  if (!fs.existsSync(filePath)) return "";
  return fs.readFileSync(filePath, "utf8");
}

function stripForContract(source) {
  return stripStringsAndComments(source);
}

function checkElevatorContract(evalDir) {
  const errors = [];
  if (!path.basename(evalDir).includes("elevator_prompt_wiggum")) return errors;

  const indexPath = path.join(evalDir, "index.html");
  const personPath = path.join(evalDir, "person.js");
  const elevatorPath = path.join(evalDir, "elevator.js");
  const hasElevatorFiles = [indexPath, personPath, elevatorPath].some((filePath) => fs.existsSync(filePath));
  if (!hasElevatorFiles) return errors;

  for (const filePath of [indexPath, personPath, elevatorPath]) {
    if (!fs.existsSync(filePath)) {
      errors.push(`${path.relative(ROOT, filePath)}: required elevator artifact is missing`);
    }
  }
  if (errors.length) return errors;

  const index = readIfExists(indexPath);
  const person = readIfExists(personPath);
  const elevator = readIfExists(elevatorPath);
  const allCode = `${index}\n${person}\n${elevator}`;
  const strippedPerson = stripForContract(person);
  const strippedElevator = stripForContract(elevator);

  const scriptSrcs = [];
  const scriptRe = /<script\b([^>]*)\bsrc\s*=\s*["']([^"']+)["']([^>]*)>\s*<\/script>/gi;
  let scriptMatch;
  while ((scriptMatch = scriptRe.exec(index))) {
    const attrs = `${scriptMatch[1]} ${scriptMatch[3]}`;
    scriptSrcs.push({ src: scriptMatch[2], attrs });
  }
  const expectedScripts = [
    "https://cdn.jsdelivr.net/npm/three@0.147.0/build/three.min.js",
    "https://cdn.jsdelivr.net/npm/three@0.147.0/examples/js/controls/OrbitControls.js",
    "person.js",
    "elevator.js",
  ];
  const actualScripts = scriptSrcs.map((item) => item.src);
  if (JSON.stringify(actualScripts) !== JSON.stringify(expectedScripts)) {
    errors.push(`${path.relative(ROOT, indexPath)}: script src order must exactly be Three 0.147.0, OrbitControls, person.js, elevator.js`);
  }
  for (const item of scriptSrcs) {
    if (/\btype\s*=\s*["']module["']/i.test(item.attrs)) {
      errors.push(`${path.relative(ROOT, indexPath)}: classic scripts required; remove type="module"`);
    }
  }
  const extraLocalScripts = actualScripts.filter((src) => !src.includes("://") && !["person.js", "elevator.js"].includes(src));
  if (extraLocalScripts.length) {
    errors.push(`${path.relative(ROOT, indexPath)}: unexpected local script(s): ${extraLocalScripts.join(", ")}`);
  }

  const forbiddenPatterns = [
    [/\bimport\b/m, "import"],
    [/\bexport\b/m, "export"],
    [/\btype\s*=\s*["']module["']/im, "type=\"module\""],
    [/file:\/\//i, "file://"],
    [/summary\.html/i, "summary.html"],
    [/<\s*iframe\b/i, "<iframe"],
    [/<\s*object\b/i, "<object"],
    [/<\s*embed\b/i, "<embed"],
  ];
  for (const [pattern, label] of forbiddenPatterns) {
    if (pattern.test(allCode)) errors.push(`elevator contract: forbidden ${label} found`);
  }

  const requiredConstants = new Map([
    ["FLOOR_HEIGHT", "3"],
    ["FLOOR_COUNT", "6"],
    ["BUILDING_WIDTH", "20"],
    ["BUILDING_DEPTH", "15"],
    ["SHAFT_WIDTH", "5"],
    ["SHAFT_DEPTH", "5"],
    ["ELEVATOR_SPEED", "2"],
    ["PERSON_MOVE_SPEED", "1"],
  ]);
  for (const [name, value] of requiredConstants.entries()) {
    const re = new RegExp(`(^|\\n)\\s*const\\s+${name}\\s*=\\s*${value}\\s*;`);
    if (!re.test(strippedElevator)) {
      errors.push(`${path.relative(ROOT, elevatorPath)}: missing top-level "const ${name} = ${value};"`);
    }
  }

  const requiredGlobals = [
    ["scene", /(^|\n)\s*let\s+scene\s*;/],
    ["camera", /(^|\n)\s*let\s+camera\s*;/],
    ["renderer", /(^|\n)\s*let\s+renderer\s*;/],
    ["controls", /(^|\n)\s*let\s+controls\s*;/],
    ["elevatorCar", /(^|\n)\s*let\s+elevatorCar\s*;/],
    ["people", /(^|\n)\s*let\s+people\s*=\s*\[\s*\]\s*;/],
  ];
  for (const [name, pattern] of requiredGlobals) {
    if (!pattern.test(strippedElevator)) {
      errors.push(`${path.relative(ROOT, elevatorPath)}: missing required top-level global "let ${name}"`);
    }
  }

  for (const forbidden of ["scene", "camera", "renderer", "controls", "elevatorCar", "people"]) {
    const re = new RegExp(`(^|\\n)\\s*(?:let|const|var)\\s+${forbidden}\\b`);
    if (re.test(strippedPerson)) {
      errors.push(`${path.relative(ROOT, personPath)}: must not declare ${forbidden}`);
    }
  }
  if (!/(^|\n)\s*function\s+createPerson\s*\(\s*color\s*\)/.test(strippedPerson)) {
    errors.push(`${path.relative(ROOT, personPath)}: must define global function createPerson(color)`);
  }
  for (const required of ["leftLeg", "rightLeg", "isWalking"]) {
    if (!new RegExp(`\\b${required}\\b`).test(strippedPerson)) {
      errors.push(`${path.relative(ROOT, personPath)}: createPerson userData must include ${required}`);
    }
  }
  if (!/new\s+THREE\.Group\s*\(/.test(strippedPerson) || !/return\s+[A-Za-z_$][A-Za-z0-9_$]*\s*;/.test(strippedPerson)) {
    errors.push(`${path.relative(ROOT, personPath)}: createPerson must create and return a THREE.Group`);
  }

  if (!/new\s+THREE\.Group\s*\(/.test(strippedElevator) || !/elevatorCar\s*=/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: elevatorCar must be assigned a THREE.Group`);
  }
  if (!/elevatorCar\.leftDoor\s*=\s*leftDoor\s*;/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: must store left door as elevatorCar.leftDoor = leftDoor;`);
  }
  if (!/elevatorCar\.rightDoor\s*=\s*rightDoor\s*;/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: must store right door as elevatorCar.rightDoor = rightDoor;`);
  }
  if (!/elevatorCar\.attach\s*\(/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: boarding must use elevatorCar.attach(...) to preserve world position`);
  }
  if (!/scene\.attach\s*\(/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: exiting must use scene.attach(...) to preserve world position`);
  }
  if (/elevatorCar\.add\s*\(\s*person/.test(strippedElevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: do not use elevatorCar.add(person) for boarding`);
  }
  if (!/startSimulation\s*\(/.test(strippedElevator) || !/DOMContentLoaded/.test(elevator)) {
    errors.push(`${path.relative(ROOT, elevatorPath)}: must auto-start startSimulation with the DOMContentLoaded pattern`);
  }

  return errors;
}

function staticCheckEval(evalDir) {
  const jsFiles = jsFilesForEval(evalDir);
  const syntaxErrors = [];
  for (const filePath of jsFiles) {
    const result = spawnSync(process.execPath, ["--check", filePath], { encoding: "utf8" });
    if (result.status !== 0) {
      const relFile = path.relative(ROOT, filePath);
      const lines = (result.stderr || result.stdout || "")
        .trim()
        .split(/\r?\n/)
        .map((line) => line.trimEnd())
        .filter((line) => line && !line.startsWith("at ") && !line.startsWith("Node.js"));
      if (lines[0] && path.resolve(lines[0].split(":").slice(0, -1).join(":")) === filePath) {
        lines[0] = lines[0].replace(filePath, relFile);
      }
      const syntaxLineIndex = lines.findIndex((line) => /^SyntaxError\b/.test(line));
      const usefulLines = syntaxLineIndex >= 0 ? lines.slice(0, syntaxLineIndex + 1) : lines.slice(0, 4);
      const message = usefulLines.join(" | ");
      syntaxErrors.push(message || `${relFile}: syntax check failed`);
    }
  }

  const globalScope = makeScope(null, "global", "");
  const projectGlobals = new Set();
  const rootDeclarations = new Map();
  for (const filePath of jsFiles) collectDeclarationsAndRefs(filePath, globalScope, projectGlobals, rootDeclarations);

  const referenceErrors = [];
  for (const child of globalScope.children) collectUnresolved(child, projectGlobals, referenceErrors);
  const duplicateErrors = [];
  for (const [name, declarations] of rootDeclarations.entries()) {
    if (declarations.length < 2) continue;
    const locations = declarations
      .map((decl) => `${path.relative(ROOT, decl.file)}:${decl.line}:${decl.column}`)
      .join(", ");
    duplicateErrors.push(`Duplicate top-level lexical declaration '${name}' in classic scripts: ${locations}`);
  }
  const contractErrors = checkElevatorContract(evalDir);
  const staticErrors = [...syntaxErrors, ...duplicateErrors, ...referenceErrors, ...contractErrors];
  return {
    checked_at: new Date().toISOString(),
    files_checked: jsFiles.map((filePath) => path.relative(ROOT, filePath)),
    static_errors: Array.from(new Set(staticErrors)).slice(0, 30),
    static_warnings: [],
  };
}

function targets(arg) {
  if (!arg || arg === "--all") {
    if (!fs.existsSync(EVALS_DIR)) return [];
    return fs.readdirSync(EVALS_DIR)
      .map((name) => path.join(EVALS_DIR, name))
      .filter((item) => fs.statSync(item).isDirectory());
  }
  const direct = path.resolve(ROOT, arg);
  return fs.existsSync(direct) && fs.statSync(direct).isDirectory() ? [direct] : [];
}

if (require.main === module) {
  const dirs = targets(process.argv[2] || "--all");
  if (!dirs.length) {
    console.error("No evaluation directories found.");
    process.exit(1);
  }
  let hadErrors = false;
  for (const dir of dirs) {
    const result = staticCheckEval(dir);
    fs.writeFileSync(path.join(dir, "static_check.json"), `${JSON.stringify(result, null, 2)}\n`, "utf8");
    if (result.static_errors.length) hadErrors = true;
    const status = result.static_errors.length ? "errors" : "ok";
    console.log(`${path.relative(ROOT, dir)}: ${status}, static check written`);
    for (const err of result.static_errors.slice(0, 5)) {
      console.log(`  - ${err}`);
    }
  }
  process.exit(hadErrors ? 2 : 0);
}

module.exports = { staticCheckEval };

#!/usr/bin/env node
const fs = require("fs");
const http = require("http");
const path = require("path");
const { staticCheckEval } = require("./static_check");

let chromium;
try {
  ({ chromium } = require("playwright"));
} catch (err) {
  console.error("Playwright is not available. Install it, or run with NODE_PATH pointing at a Playwright node_modules directory.");
  console.error(`Load error: ${err && err.message ? err.message : err}`);
  console.error("Example: npm install --save-dev playwright && node runtime_check.js --all");
  process.exit(1);
}

const ROOT = process.cwd();
const EVALS_DIR = path.join(ROOT, "evals");
const PREVIEW_FILES = ["index.html", "elevator_sim.html", "elevator_simulation.html", "test.html"];

function contentType(filePath) {
  const ext = path.extname(filePath).toLowerCase();
  return {
    ".html": "text/html; charset=utf-8",
    ".js": "text/javascript; charset=utf-8",
    ".css": "text/css; charset=utf-8",
    ".json": "application/json; charset=utf-8",
    ".png": "image/png",
    ".jpg": "image/jpeg",
    ".jpeg": "image/jpeg",
    ".gif": "image/gif",
  }[ext] || "application/octet-stream";
}

function startServer() {
  const server = http.createServer((req, res) => {
    const urlPath = decodeURIComponent((req.url || "/").split("?")[0]);
    const requested = path.resolve(ROOT, `.${urlPath}`);
    if (!requested.startsWith(ROOT)) {
      res.writeHead(403);
      res.end("Forbidden");
      return;
    }
    fs.readFile(requested, (err, data) => {
      if (err) {
        res.writeHead(404);
        res.end("Not found");
        return;
      }
      res.writeHead(200, { "Content-Type": contentType(requested) });
      res.end(data);
    });
  });
  return new Promise((resolve) => {
    server.listen(0, "127.0.0.1", () => resolve(server));
  });
}

function previewFile(evalDir) {
  for (const name of PREVIEW_FILES) {
    const candidate = path.join(evalDir, name);
    if (fs.existsSync(candidate)) return name;
  }
  return null;
}

function printUsage() {
  console.log(`Usage: node runtime_check.js <eval-dir> | --all

Runs a headless-browser smoke check (static check + canvas/animation probe)
against one or more evaluation runs, writing runtime_check.json into each.

Arguments:
  <eval-dir>     Process a single evaluation run. Accepts a bare run name
                 (e.g. claude_sonnet-4_prompt1), a path relative to evals/,
                 or a path relative to the repo root.
  --all          Process every evaluation run under evals/.
  -h, --help     Show this help message.

Examples:
  node runtime_check.js claude_sonnet-4_prompt1
  node runtime_check.js evals/claude_sonnet-4_prompt1
  node runtime_check.js --all`);
}

function resolveEvalDir(arg) {
  const candidates = [
    path.resolve(ROOT, arg),
    path.join(EVALS_DIR, arg),
  ];
  for (const candidate of candidates) {
    if (fs.existsSync(candidate) && fs.statSync(candidate).isDirectory()) {
      return candidate;
    }
  }
  return null;
}

function evalTargets(arg) {
  if (arg === "--all") {
    if (!fs.existsSync(EVALS_DIR)) return [];
    return fs.readdirSync(EVALS_DIR)
      .map((name) => path.join(EVALS_DIR, name))
      .filter((item) => fs.statSync(item).isDirectory() && previewFile(item));
  }
  const evalDir = resolveEvalDir(arg);
  if (!evalDir) {
    console.error(`No evaluation directory found for "${arg}".`);
    console.error(`Looked for: ${path.resolve(ROOT, arg)}`);
    console.error(`        and: ${path.join(EVALS_DIR, arg)}`);
    return [];
  }
  if (!previewFile(evalDir)) {
    console.error(`"${path.relative(ROOT, evalDir)}" has no preview file (${PREVIEW_FILES.join(", ")}).`);
    return [];
  }
  return [evalDir];
}

async function canvasSnapshot(page) {
  return await page.evaluate(() => {
    const canvases = Array.from(document.querySelectorAll("canvas"));
    const canvas = canvases[0];
    if (!canvas) {
      return { canvas_count: 0, nonblank_canvas: false, complexity: 0, checksum: "", error: "" };
    }
    try {
      const dataUrl = canvas.toDataURL("image/png");
      let checksum = 0;
      const buckets = new Set();
      for (let i = 0; i < dataUrl.length; i += 97) {
        const code = dataUrl.charCodeAt(i);
        checksum = (checksum + code * (i + 1)) % 1000000007;
        buckets.add(code >> 3);
      }
      return {
        canvas_count: canvases.length,
        nonblank_canvas: dataUrl.length > 3000 && buckets.size > 2,
        complexity: buckets.size,
        checksum: String(checksum),
        error: "",
      };
    } catch (err) {
      return { canvas_count: canvases.length, nonblank_canvas: false, complexity: 0, checksum: "", error: String(err && err.message || err) };
    }
  });
}

async function boostSimulationControls(page) {
  await page.evaluate(() => {
    for (const input of Array.from(document.querySelectorAll("input[type='range']"))) {
      if (input.max) {
        input.value = input.max;
        input.dispatchEvent(new Event("input", { bubbles: true }));
        input.dispatchEvent(new Event("change", { bubbles: true }));
      }
    }
  }).catch(() => {});
}

async function probeEval(browser, serverPort, evalDir) {
  const staticCheck = staticCheckEval(evalDir);
  const preview = previewFile(evalDir);
  const rel = path.relative(ROOT, path.join(evalDir, preview)).replace(/\\/g, "/");
  const url = `http://127.0.0.1:${serverPort}/${rel}`;
  const consoleErrors = [];
  const pageErrors = [];
  const warnings = [];
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });

  await page.addInitScript(() => {
    window.__llmEvalRuntime = {
      frames: 0,
      objectCount: 0,
      objectChanges: 0,
      threePatched: false,
    };
    const originalRequestAnimationFrame = window.requestAnimationFrame;
    window.requestAnimationFrame = function patchedRequestAnimationFrame(callback) {
      return originalRequestAnimationFrame.call(window, function countedFrame(ts) {
        window.__llmEvalRuntime.frames += 1;
        return callback(ts);
      });
    };
    const patchTimer = window.setInterval(() => {
      const THREE = window.THREE;
      if (!THREE || !THREE.Object3D || window.__llmEvalRuntime.threePatched) return;
      window.__llmEvalRuntime.threePatched = true;
      const seen = new WeakSet();
      const lastPositions = new WeakMap();
      const originalUpdateMatrixWorld = THREE.Object3D.prototype.updateMatrixWorld;
      THREE.Object3D.prototype.updateMatrixWorld = function patchedUpdateMatrixWorld(...args) {
        try {
          if (!seen.has(this)) {
            seen.add(this);
            window.__llmEvalRuntime.objectCount += 1;
          }
          if (this.position) {
            const pos = `${this.position.x.toFixed(3)},${this.position.y.toFixed(3)},${this.position.z.toFixed(3)}`;
            const last = lastPositions.get(this);
            if (last && last !== pos) {
              window.__llmEvalRuntime.objectChanges += 1;
            }
            lastPositions.set(this, pos);
          }
        } catch (err) {
          // Instrumentation should never break the evaluated artifact.
        }
        return originalUpdateMatrixWorld.apply(this, args);
      };
      window.clearInterval(patchTimer);
    }, 10);
  });

  page.on("console", (msg) => {
    if (msg.type() === "error") consoleErrors.push(msg.text());
  });
  page.on("pageerror", (err) => pageErrors.push(err.message));

  const started = Date.now();
  let loaded = false;
  try {
    await page.goto(url, { waitUntil: "domcontentloaded", timeout: 10000 });
    loaded = true;
    await page.waitForTimeout(1200);
    await boostSimulationControls(page);
    await page.waitForTimeout(300);
  } catch (err) {
    pageErrors.push(String(err && err.message || err));
  }

  const first = await canvasSnapshot(page);
  await page.waitForTimeout(4200);
  const second = await canvasSnapshot(page);
  const runtimeStats = await page.evaluate(() => window.__llmEvalRuntime || {}).catch(() => ({}));
  const frames = Number(runtimeStats.frames || 0);
  const objectCount = Number(runtimeStats.objectCount || 0);
  const objectChanges = Number(runtimeStats.objectChanges || 0);

  if (first.error || second.error) warnings.push(`Canvas sampling issue: ${first.error || second.error}`);

  await page.close();
  return {
    checked_at: new Date().toISOString(),
    url,
    static_errors: staticCheck.static_errors,
    static_warnings: staticCheck.static_warnings,
    static_files_checked: staticCheck.files_checked,
    loaded,
    console_errors: consoleErrors.slice(0, 10),
    page_errors: pageErrors.slice(0, 10),
    canvas_count: Math.max(first.canvas_count || 0, second.canvas_count || 0),
    nonblank_canvas: Boolean(first.nonblank_canvas || second.nonblank_canvas),
    animation_frames: frames,
    scene_object_count: objectCount,
    dynamic_changes: objectChanges,
    canvas_changed: Boolean(first.checksum && second.checksum && first.checksum !== second.checksum),
    duration_ms: Date.now() - started,
    warnings,
  };
}

async function main() {
  const arg = process.argv[2];
  if (!arg || arg === "-h" || arg === "--help") {
    printUsage();
    process.exit(arg ? 0 : 1);
  }
  const targets = evalTargets(arg);
  if (!targets.length) {
    console.error("No evaluation directories with previews found.");
    process.exit(1);
  }
  const server = await startServer();
  const port = server.address().port;
  const browser = await chromium.launch({ headless: true });
  try {
    for (const evalDir of targets) {
      const result = await probeEval(browser, port, evalDir);
      const outPath = path.join(evalDir, "runtime_check.json");
      fs.writeFileSync(outPath, `${JSON.stringify(result, null, 2)}\n`, "utf8");
      let status = "ok";
      if (result.static_errors.length || result.console_errors.length || result.page_errors.length || !result.loaded) {
        status = "errors";
      } else if (!result.canvas_count || !result.nonblank_canvas) {
        status = "no-canvas";
      } else if (result.animation_frames < 2) {
        status = "no-animation";
      } else if (result.dynamic_changes <= 0) {
        status = "no-motion";
      }
      console.log(`${path.relative(ROOT, evalDir)}: ${status}, R probe written`);
      console.log(
        `  metrics: loaded=${result.loaded} canvas=${result.canvas_count} nonblank=${result.nonblank_canvas} frames=${result.animation_frames} objects=${result.scene_object_count} changes=${result.dynamic_changes}`
      );
      const details = [
        ...result.static_errors.map((err) => `static: ${err}`),
        ...result.page_errors.map((err) => `page: ${err}`),
        ...result.console_errors.map((err) => `console: ${err}`),
        ...result.warnings.map((err) => `warning: ${err}`),
      ];
      for (const detail of details.slice(0, 5)) {
        console.log(`  - ${detail}`);
      }
    }
  } finally {
    await browser.close();
    server.close();
  }
}

main().catch((err) => {
  console.error(err && err.stack || err);
  process.exit(1);
});

